const e=[{id:"sv-3-531",phase:3,topic:"3.1.2",qtype:"concept",difficulty:1,stem:"What does **kurtosis** describe in a distribution?",options:["The direction in which the distribution leans","The number of distinct values the data can take","The location of the centre of the data","The height of the peak and the weight of the tails"],answer:3,hint:"Kurtosis is the class of non-normality about the shape of the peak and tails.",steps:[{title:"Key idea",body:"The book: kurtosis describes **the peak and the tails** — tall and long-tailed (leptokurtic) or flat and short-tailed (platykurtic)."},{title:"Eliminate look-alikes",body:"Direction = skewness, few values = granularity, centre = location statistics."}],final:"Kurtosis = peak and tails → answer **D**",whyWrong:["Incorrect — the direction of lean is skewness, the first class of non-normality.","Incorrect — few distinct values is granularity, a resolution problem.","Incorrect — the centre is described by the mean, median or mode.",""],bookRef:"Book pp. 260–261"},{id:"sv-3-532",phase:3,topic:"3.1.2",qtype:"concept",difficulty:1,stem:"What are the mean and standard deviation of the **standard normal (Z)** distribution?",options:["Mean 1 and standard deviation 0","Mean 0 and standard deviation 1","Mean 0 and standard deviation 3","Mean 50 and standard deviation 10"],answer:1,hint:"Z values count standard deviations from the mean.",steps:[{title:"Key idea",body:"The book: the standard normal (Z) distribution has **mean 0 and standard deviation 1**."},{title:"Eliminate look-alikes",body:"Any normal variable is converted to Z by measuring its distance from the mean in SD units."}],final:"Z: mean 0, SD 1 → answer **B**",whyWrong:["Incorrect — a standard deviation of 0 would mean no spread at all; the roles of 0 and 1 are swapped.","","Incorrect — 3 is the number of standard deviations to a control limit, not the SD of Z.","Incorrect — these are arbitrary scale values; the Z distribution is centred on 0."],bookRef:"Book p. 255"},{id:"sv-3-533",phase:3,topic:"3.1.2",qtype:"concept",difficulty:2,stem:"Why does the book tell a team to 'celebrate' when it finds a **bimodal** distribution?",options:["A bimodal process is always capable of meeting its specification","Bimodal data always pass the Anderson-Darling normality test","It proves that the measurement system has enough resolution","Its causes are usually easy to find by asking what separates the two groups"],answer:3,hint:"Think about how hard it is to find the cause when the data split into two clear groups.",steps:[{title:"Key idea",body:"Multiple modes usually come from **mixtures** (2 machines, 2 operators). The book says these causes are usually the **easiest to find**."},{title:"Apply to the stem",body:"The team only has to ask what is different between the two groups, so the root-cause search is short."},{title:"Eliminate look-alikes",body:"Capability, normality and resolution are separate questions."}],final:"Bimodal causes are easy to find → answer **D**",whyWrong:["Incorrect — capability compares the process with the specification; the shape alone says nothing about meeting it.","Incorrect — bimodal data usually fail normality; the book's example has p < 0.005.","Incorrect — resolution is a granularity question, checked through MSA, not through two peaks.",""],bookRef:"Book pp. 262–263"},{id:"sv-3-534",phase:3,topic:"3.1.2",qtype:"concept",difficulty:1,stem:"Which property belongs to the **normal** distribution?",options:["The curve meets the horizontal axis at ±3 standard deviations","The mean is pulled towards the longer tail","The skewness coefficient is clearly positive","The mean, median and mode are equal"],answer:3,hint:"Recall the book's list of features of the mounded, symmetric curve.",steps:[{title:"Key idea",body:"The normal curve is mounded and symmetric, with total area 1, and **mean = median = mode**."},{title:"Eliminate look-alikes",body:"It never touches the axis, and the pull of the mean toward a tail is a sign of skewness."}],final:"Normal: mean = median = mode → answer **D**",whyWrong:["Incorrect — the normal curve extends forever, getting close to the axis but never touching it.","Incorrect — a mean pulled toward a long tail describes a skewed distribution.","Incorrect — a positive skewness coefficient means right skew; a normal curve is about 0.",""],bookRef:"Book p. 255"},{id:"sv-3-535",phase:3,topic:"3.1.2",qtype:"concept",difficulty:2,stem:"Minitab draws a normal curve over a histogram of **pump flow rate**. What does that curve represent?",options:["The actual shape of the data after Minitab smooths the bars","A theoretical curve built from the sample's mean and standard deviation","The specification limits converted into a distribution","The population shape after the outliers have been removed"],answer:1,hint:"The book warns that the curve over a histogram is not your data.",steps:[{title:"Key idea",body:"The book: the normal curve is **not your data** — it is a theoretical curve built from the sample mean and standard deviation."},{title:"Apply to the stem",body:"Compare the bars with the curve to judge the shape; do not read the curve as the data."},{title:"Eliminate look-alikes",body:"Specs and outlier removal play no part in drawing it."}],final:"Overlay = theoretical curve from mean and SD → answer **B**",whyWrong:["Incorrect — the curve is not the data; the bars are the data and the curve is a model laid over them.","","Incorrect — specification limits are the voice of the customer and are not used to draw the curve.","Incorrect — Minitab removes nothing; the curve uses all the data's mean and SD."],bookRef:"Book p. 255",trap:"A histogram can look 'normal' only because the eye follows the overlaid curve."},{id:"sv-3-536",phase:3,topic:"3.1.2",qtype:"concept",difficulty:2,stem:"A field technician is equally likely to arrive at any moment within a promised **4-hour window**. Which distribution BEST describes the arrival time within the window?",options:["Exponential","Normal","Poisson","Uniform"],answer:3,hint:"Every moment in the window is equally likely.",steps:[{title:"Key idea",body:"Equal likelihood across a fixed range is the **uniform** distribution: its histogram is flat across the window."},{title:"Eliminate look-alikes",body:"Exponential = waiting time between random events; Poisson = counts; normal = mounded around the mean."}],final:"Equally likely in a range = uniform → answer **D**",whyWrong:["Incorrect — the exponential models time between random events, with short times most likely.","Incorrect — a normal shape would make arrivals near the middle of the window most likely.","Incorrect — the Poisson models counts of events, not a time within a window.",""],bookRef:"Syllabus 3.1.2"},{id:"sv-3-537",phase:3,topic:"3.1.2",qtype:"concept",difficulty:2,stem:"Which **two causes of granularity** does the book give?",options:["Mixtures of machines and sorting of product","Measurement resolution and categorical (step-type) data","Natural limits and artificial limits","Tool wear and warm-up effects"],answer:1,hint:"Granular data take only a few values — why might that happen?",steps:[{title:"Key idea",body:"Granularity: **4-1 measurement system resolution** (the gauge cannot see small differences) and **4-2 categorical, step-type data**."},{title:"Eliminate look-alikes",body:"The other pairs belong to skewness, kurtosis and multiple modes."}],final:"Granularity = resolution or step-type data → answer **B**",whyWrong:["Incorrect — mixtures and sorting are causes of kurtosis and multiple modes.","","Incorrect — natural and artificial limits are causes of skewness.","Incorrect — tool wear and warm-up are non-random patterns over time."],bookRef:"Book p. 263"},{id:"sv-3-538",phase:3,topic:"3.1.2",qtype:"concept",difficulty:3,stem:"Why does the book say non-normal data often carry **more** root-cause information than normal data?",options:["Non-normal data always have less variation than normal data","Non-parametric tests are always more powerful than parametric tests","The shape points to why the data depart from pure random variation","Non-normal data do not need a normality check before a test"],answer:2,hint:"Normal shape = only random variation. What does a different shape add?",steps:[{title:"Key idea",body:"Normal data show only 'white noise'. A non-normal shape has a **reason** — mixtures, limits, trends, resolution."},{title:"Apply to the stem",body:"Each class has typical causes, so the shape itself is a clue for X-sifting."},{title:"Eliminate look-alikes",body:"Power of tests and amount of variation are other questions."}],final:"Shape = clue to the cause → answer **C**",whyWrong:["Incorrect — non-normality says nothing about the size of the variation.","Incorrect — non-parametric tests are generally less powerful; the book's point is about the shape.","","Incorrect — the book says to check normality before every statistical test."],bookRef:"Book p. 264"},{id:"sv-3-539",phase:3,topic:"3.1.2",qtype:"concept",difficulty:2,stem:"Which statement about **mixtures** is CORRECT, according to the book?",options:["They are the only cause of granular data","They are a natural state that needs no further action","They cannot be seen on a histogram of the data","They can cause skewness, kurtosis and multiple modes"],answer:3,hint:"Look for mixtures in the cause lists of each class.",steps:[{title:"Key idea",body:"Mixtures appear in three lists: skewness cause 3, kurtosis cause 2-1 and multiple modes cause 3-1."},{title:"Eliminate look-alikes",body:"They are a problem to separate, not a natural state, and they are not a granularity cause."}],final:"Mixtures → skew, kurtosis, multiple modes → answer **D**",whyWrong:["Incorrect — granularity comes from resolution or step-type data, not mixtures.","Incorrect — only skewness from natural limits is called a natural state; mixtures should be separated.","Incorrect — mixtures often show as two peaks or a strange peak on a histogram.",""],bookRef:"Book pp. 255–264"},{id:"sv-3-540",phase:3,topic:"3.1.2",qtype:"concept",difficulty:1,stem:"Which statement about the **skewness coefficient** reported by Minitab is CORRECT?",options:["A negative value means the long tail is on the right","A value close to zero suggests roughly symmetric data","A positive value means the mean is below the median","A value close to 3 indicates a normal shape"],answer:1,hint:"Recall the sign rule for skewness.",steps:[{title:"Key idea",body:"Skewness ≈ 0 symmetric; > 0 right skew; < 0 left skew. The mean is pulled toward the long tail."},{title:"Eliminate look-alikes",body:"The book's right-skewed example: mean 70.0, median 65.7, skewness +2.42."}],final:"Skewness ≈ 0 = symmetric → answer **B**",whyWrong:["Incorrect — a negative value is left skew: the long tail is on the left.","","Incorrect — with right (positive) skew the mean is pulled above the median.","Incorrect — 3 is a raw kurtosis convention, not a skewness value; normal skewness is about 0."],bookRef:"Book pp. 257–258"},{id:"sv-3-541",phase:3,topic:"3.1.2",qtype:"concept",difficulty:2,stem:"Which statement about data that already look **normal** is CORRECT, according to the book?",options:["They show that the process cannot be improved further","They prove that the process meets its specification","They can still be improved by reducing the variation","They no longer need a normality test before analysis"],answer:2,hint:"Normal means only random variation — but how much?",steps:[{title:"Key idea",body:"The book: data that look normal **can still be improved** — reduce the variation to create a narrower normal distribution."},{title:"Eliminate look-alikes",body:"Shape is not capability, and looking normal is not a test result."}],final:"Normal ≠ finished → answer **C**",whyWrong:["Incorrect — the book says normal data can still be improved into a new, narrower normal distribution.","Incorrect — a normal shape says nothing about the specification; that is capability.","","Incorrect — the normality check is still done; a normal look is not proof."],bookRef:"Book p. 255"},{id:"sv-3-542",phase:3,topic:"3.1.2",qtype:"statements",difficulty:2,stem:`Which statements about **kurtosis** are CORRECT?

1. A leptokurtic distribution has a tall peak and long tails.
2. A platykurtic distribution has a positive kurtosis value.
3. Mixtures cannot cause kurtosis.
4. Scrapping product outside the specification limits can produce kurtosis.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Lepto = leaping peak; platy = flat plate. Then recall the four causes of kurtosis.",steps:[{title:"Key idea",body:"Leptokurtic = peaked, long tails, positive value. Platykurtic = flat, short tails, negative value."},{title:"Apply to the stem",body:"Causes of kurtosis: mixtures, sorting or selecting (scrapping out-of-spec product), trends, non-linear relationships. So 1 and 4 are true."},{title:"Eliminate look-alikes",body:"2 reverses the sign; 3 removes the first cause on the list."}],final:"True: 1 and 4 → answer **D**",whyWrong:["Incorrect — statement 2 is false: platykurtic data have a negative kurtosis value.","Incorrect — both are false: platykurtic is negative, and mixtures are the first cause listed.","Incorrect — statement 3 is false: the book lists mixtures (2-1) as a cause of kurtosis.",""],bookRef:"Book pp. 260–261"},{id:"sv-3-543",phase:3,topic:"3.1.2",qtype:"statements",difficulty:3,stem:`Which statements about **multiple modes** are CORRECT?

1. Mixtures of distributions are the most likely cause.
2. Lack of independence, such as trends, can also produce them.
3. A bimodal distribution always comes from a single, stable source.
4. Several outliers usually point to one single input.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Recall the book's reasons for separate peaks, and what it says about outliers.",steps:[{title:"Key idea",body:"Reasons for multiple modes: 3-1 mixtures (most likely), 3-2 lack of independence, 3-3 catastrophic failures."},{title:"Apply to the stem",body:"So 1 and 2 are true. A single outlier has its own cause; **multiple** outliers usually mean several inputs."},{title:"Eliminate look-alikes",body:"3 contradicts the mixture idea and 4 reverses the outlier rule."}],final:"True: 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: two peaks normally mean two different sources, such as two machines.","Incorrect — both are false: two peaks suggest two sources, and several outliers suggest several inputs.","Incorrect — statement 4 is false: the book says multiple outliers usually involve several inputs."],bookRef:"Book pp. 262–263"},{id:"sv-3-544",phase:3,topic:"3.1.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A process that shows only pure random variation, or 'white noise', produces a [?] distribution.`,options:["bimodal","normal","platykurtic","skewed"],answer:1,hint:"Which shape appears when there is no special reason behind the variation?",steps:[{title:"Key idea",body:"The book: a normal shape appears when a process has only **pure random variation** ('white noise')."},{title:"Eliminate look-alikes",body:"Every other shape has a typical cause."}],final:"White noise → normal → answer **B**",whyWrong:["Incorrect — bimodal data suggest a mixture of two sources, not pure random variation.","","Incorrect — a flat platykurtic shape suggests means shifting over time.","Incorrect — skewness comes from limits, mixtures, non-linearity or patterns, not white noise alone."],bookRef:"Book p. 255"},{id:"sv-3-545",phase:3,topic:"3.1.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The total area under the normal curve is equal to [?].`,options:["0.5","1","3","6"],answer:1,hint:"The whole curve represents all possible outcomes.",steps:[{title:"Key idea",body:"The book: the total area under the normal curve is **1** (100% of outcomes)."},{title:"Eliminate look-alikes",body:"The mean splits it 50/50, so each half has area 0.5."}],final:"Total area = 1 → answer **B**",whyWrong:["Incorrect — 0.5 is the area on one side of the mean, not the total.","","Incorrect — 3 is the number of standard deviations to each control limit, not an area.","Incorrect — 6 is the number of standard deviations across ±3σ, not an area."],bookRef:"Book p. 255"},{id:"sv-3-546",phase:3,topic:"3.1.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Many hypothesis tests [?] normality, so if the data are not normal those tests cannot be used to infer anything about the future.`,options:["assume","ignore","prove","transform"],answer:0,hint:"Why does every test on the roadmap start with a normality check?",steps:[{title:"Key idea",body:"The book: many tests **assume** normality; if the assumption fails, the result cannot be trusted for inference."},{title:"Eliminate look-alikes",body:"Hence the rule: check normality before every statistical test."}],final:"Tests assume normality → answer **A**",whyWrong:["","Incorrect — if tests ignored normality, non-normal data would not limit them.","Incorrect — a test cannot prove normality; a normality test can only fail to reject it.","Incorrect — tests do not transform data; transformation is a separate choice the analyst makes."],bookRef:"Book p. 256"},{id:"sv-3-547",phase:3,topic:"3.1.2",qtype:"not-except",difficulty:2,stem:"The book lists four causes of **kurtosis**. Which is NOT one of them?",options:["Mixtures of set-ups, batches or machines","Sorting or selecting, such as scrapping out-of-spec product","Trends or patterns caused by a lack of independence","Measurement system resolution"],answer:3,hint:"Three are the book's kurtosis causes; one belongs to another class.",steps:[{title:"Key idea",body:"Kurtosis causes: 2-1 mixtures, 2-2 sorting or selecting, 2-3 trends or patterns, 2-4 non-linear relationships."},{title:"Apply to the stem",body:"Measurement resolution is cause 4-1 of **granularity**, not kurtosis."}],final:"Resolution belongs to granularity → answer **D**",whyWrong:["Incorrect — mixtures (2-1) are the first cause of kurtosis in the book.","Incorrect — sorting or selecting (2-2) is a listed cause of kurtosis.","Incorrect — trends or patterns (2-3), such as tool wear, are a listed cause.",""],bookRef:"Book p. 261"},{id:"sv-3-548",phase:3,topic:"3.1.2",qtype:"not-except",difficulty:2,stem:"Which observation is NOT a sign of **granular** data?",options:["Only a few distinct values appear in the data","A dot plot that looks like a set of stacked steps","A symmetric shape that still fails the normality test","Two separate peaks far apart on the histogram"],answer:3,hint:"Three describe too few values; one describes two sources.",steps:[{title:"Key idea",body:"Granularity: few distinct values, stepped dot plot, symmetric but p < 0.05 because of poor resolution."},{title:"Apply to the stem",body:"Two separate peaks are a sign of **multiple modes**, usually a mixture of sources."}],final:"Two peaks = multiple modes, not granularity → answer **D**",whyWrong:["Incorrect — few distinct values is the definition of granular data.","Incorrect — the book says granular data are easy to see as steps on a dot plot.","Incorrect — the book warns that granular data can look symmetric yet fail normality.",""],bookRef:"Book pp. 262–263"},{id:"sv-3-549",phase:3,topic:"3.1.2",qtype:"not-except",difficulty:2,stem:"A team finds that its **delivery lead-time** data are non-normal. All of the following are appropriate next steps EXCEPT:",options:["Look at the shape to decide which class of non-normality is present","Conclude that the process is broken and stop analysing the data","Stratify the data by depot or driver to check for a mixture","Ask a Master Black Belt before deciding to transform the data"],answer:1,hint:"The book's message is that non-normal data are not bad.",steps:[{title:"Key idea",body:"Non-normal data are **not bad** — they carry root-cause clues."},{title:"Apply to the stem",body:"Reading the class, stratifying and consulting an MBB all follow the book. Declaring the process broken and stopping does not."}],final:"Non-normal ≠ broken → answer **B**",whyWrong:["Incorrect — reading the shape is the book's first move: each class has typical causes.","","Incorrect — stratifying checks for mixtures, the most common cause of odd shapes.","Incorrect — the book advises asking an MBB rather than rushing into a transformation."],bookRef:"Book pp. 264, 370"},{id:"sv-3-550",phase:3,topic:"3.1.2",qtype:"scenario",difficulty:2,stem:"Customer satisfaction is scored on a **1–5 scale** and analysed as if it were continuous. The histogram shows five bars, looks roughly symmetric and fails the Anderson-Darling test (p < 0.005). Which explanation from the book BEST fits?",options:["Multiple modes caused by a mixture of customer types","Skewness caused by an artificial limit at 5","Granularity caused by categorical, step-type data","Kurtosis caused by sorting out low scores"],answer:2,hint:"How many distinct values can this measure take?",steps:[{title:"Key idea",body:"Granularity cause 4-2: **categorical (step-type) data** — the characteristic itself only takes a few values."},{title:"Apply to the stem",body:"A 1–5 score has five possible values, so it looks symmetric but fails normality."},{title:"Eliminate look-alikes",body:"No second peak, tail or sorting is described."}],final:"1–5 scale = step-type granular data → answer **C**",whyWrong:["Incorrect — the shape is symmetric with one hump, not two separate peaks.","Incorrect — the histogram is roughly symmetric, so skewness is not the issue.","","Incorrect — nothing in the stem suggests that low scores were removed."],bookRef:"Book p. 263"},{id:"sv-3-551",phase:3,topic:"3.1.2",qtype:"scenario",difficulty:3,stem:"**Order lead time** is right-skewed: most orders take 1–3 days, a few take 10 or more, and no order can take less than zero. A team member proposes deleting the long-tail orders so that the data 'look normal'. Which response BEST follows the book?",options:["Delete the tail orders, because skewed data are always a sign of a broken process","Delete the tail orders, because non-normal data cannot be analysed","Keep the data: skew near a natural limit is a natural state, so analyse it with methods that suit skewed data","Keep the data, but report the mean only, because it is not affected by the tail"],answer:2,hint:"What does the book call skew near a limit — a problem or a natural state?",steps:[{title:"Key idea",body:"The book: **skewness** is a natural state for data near a natural limit such as zero."},{title:"Apply to the stem",body:"Deleting real orders would bias the baseline; keep them and use methods that suit skewed data (median tests)."},{title:"Eliminate look-alikes",body:"The mean is the statistic most distorted by the tail."}],final:"Do not delete natural skew → answer **C**",whyWrong:["Incorrect — the book says non-normal data are not bad, and skew near a limit is natural.","Incorrect — non-normal continuous data can be analysed, for example with median tests.","","Incorrect — the mean is pulled toward the long tail; the median is the robust centre."],bookRef:"Book pp. 257, 264, 370"},{id:"sv-3-552",phase:3,topic:"3.1.2",qtype:"scenario",difficulty:2,stem:"A lathe's cutting tool wears during each shift, so the turned diameter drifts steadily upward until the tool is changed. Data pooled over many shifts are clearly non-normal. Which cause in the book's list BEST explains the shape?",options:["Interactions between two inputs","Artificial limits from sorting","Measurement system resolution","Non-random patterns across time"],answer:3,hint:"Look at what changes during each shift.",steps:[{title:"Key idea",body:"The book's skewness cause 6 is **non-random patterns across time** — tool wear, chemical bath depletion, warm-up."},{title:"Apply to the stem",body:"Tool wear moves the diameter in a pattern, so the pooled data are not one random distribution."},{title:"Eliminate look-alikes",body:"No interaction, sorting or resolution issue is described."}],final:"Tool wear = pattern over time → answer **D**",whyWrong:["Incorrect — an interaction needs two inputs combining; here one input changes over time.","Incorrect — nothing was sorted or scrapped; the shape comes from drift.","Incorrect — resolution makes data granular; the drift is real process movement.",""],bookRef:"Book p. 258"},{id:"sv-3-553",phase:3,topic:"3.1.2",qtype:"scenario",difficulty:3,stem:"A sensor logs bath temperature **every second**. Consecutive readings are almost identical, and the temperature wanders slowly between two levels during the day. A histogram of the readings shows two humps. Which reason from the book BEST explains the shape?",options:["Catastrophic failure of the heating element","Lack of independence, such as a trend or pattern in the data","Measurement system resolution that is too coarse","A natural limit on the temperature reading"],answer:1,hint:"What is special about readings taken one second apart?",steps:[{title:"Key idea",body:"The book lists **lack of independence** (trends or patterns) as reason 3-2 for multiple modes."},{title:"Apply to the stem",body:"Readings one second apart are not independent, and the slow wander between two levels produces two humps."},{title:"Eliminate look-alikes",body:"No failure, resolution or limit effect is described."}],final:"Dependent, wandering data → multiple modes → answer **B**",whyWrong:["Incorrect — a catastrophic failure gives a separate cluster such as zero readings; here the process wanders.","","Incorrect — coarse resolution gives few stepped values, not two humps from a wandering process.","Incorrect — a natural limit stretches one tail; it does not create two humps."],bookRef:"Book p. 262"},{id:"sv-3-554",phase:3,topic:"3.1.2",qtype:"best-action",difficulty:3,stem:"A Green Belt finds that **handset repair time** is non-normal. She immediately applies a transformation so that she can run a t-test, without looking at why the data are non-normal. Was this an appropriate action?",options:["Yes, because transformed data always meet the assumptions of every test","Yes, because the cause of non-normality does not matter in Analyze","No, because the shape may reveal a root cause that the transformation would hide","No, because transformations can only be applied to attribute data"],answer:2,hint:"The book says not to rush to transform.",steps:[{title:"Key idea",body:"The book: do not rush to transform; ask an MBB. Data are often 'beaten into submission' while the real cause is ignored."},{title:"Apply to the stem",body:"Non-normal shapes carry root-cause clues, so she should first ask why the data are non-normal."},{title:"Eliminate look-alikes",body:"Both 'Yes' options ignore that warning; the last 'No' reason is false."}],final:"Look for the cause before transforming → answer **C**",whyWrong:["Incorrect — a transformation does not guarantee every assumption; the book warns against 'beating data into submission'.","Incorrect — in Analyze the cause of the shape is exactly what the team is hunting for.","","Incorrect — transformations such as Box-Cox are used on continuous data, not only attribute data."],bookRef:"Book pp. 264, 370"},{id:"sv-3-555",phase:3,topic:"3.1.2",qtype:"best-action",difficulty:1,stem:"A Green Belt is about to compare the mean **cure time** of two ovens with a 2-sample t-test. What should she do FIRST?",options:["Transform both samples with Box-Cox","Check each sample for normality","Remove the largest values from each sample","Switch to a median test without checking"],answer:1,hint:"Book rule for every statistical test.",steps:[{title:"Key idea",body:"The book: **with every statistical test, check normality first** (Anderson-Darling: p > 0.05 → fail to reject normality)."},{title:"Apply to the stem",body:"The result decides whether the t-test is valid or whether a median test is needed."},{title:"Eliminate look-alikes",body:"Transforming, trimming or switching tests all come later, if at all."}],final:"Normality check first → answer **B**",whyWrong:["Incorrect — a transformation is not the first step; the data may already be normal.","","Incorrect — deleting values without a known cause biases the comparison.","Incorrect — the choice between a mean test and a median test depends on the normality check."],bookRef:"Book p. 264"},{id:"sv-3-556",phase:3,topic:"3.1.2",qtype:"output",difficulty:3,stem:`Bearing temperatures from two lines are pooled. Line A's process is very consistent; line B's varies widely.

\`\`\`
Descriptive Statistics: Bearing_Temp
N     Mean    StDev   Median   Skewness   Kurtosis
240   61.8    3.9     61.7     0.06       3.14
\`\`\`

Which interpretation is BEST supported by the output and the context?`,options:["Platykurtic shape, consistent with several means shifting over time","Strong right skew, consistent with a natural limit at zero","Leptokurtic shape, consistent with distributions of very different variances laid on top of each other","Granular shape, consistent with poor gauge resolution"],answer:2,hint:"Read the kurtosis sign, then match the cause to the context.",steps:[{title:"Key idea",body:"Positive kurtosis = **leptokurtic** (tall peak, long tails). The book's cause: distributions with very different variances combined."},{title:"Apply to the stem",body:"Kurtosis 3.14 is clearly positive, skewness 0.06 is near 0, and the two lines have very different spreads."},{title:"Eliminate look-alikes",body:"Negative kurtosis would be platykurtic; skew and granularity are not shown."}],final:"Kurtosis +3.14 with mixed spreads = leptokurtic → answer **C**",whyWrong:["Incorrect — platykurtic data have negative kurtosis; this value is clearly positive.","Incorrect — skewness is about 0.06, so the data are roughly symmetric.","","Incorrect — nothing in the output or context points to few distinct values."],bookRef:"Book pp. 260–261"},{id:"sv-3-557",phase:3,topic:"3.1.2",qtype:"output",difficulty:2,stem:`Shape statistics for three data sets:

\`\`\`
Descriptive Statistics
Variable     N     Skewness   Kurtosis
Set_A        80    0.04       -1.12
Set_B        80    2.31        6.05
Set_C        80    0.02        0.06
\`\`\`

Which statement is CORRECT?`,options:["Set A is leptokurtic, and Set B is close to the normal shape","Set C is platykurtic, and Set A is right-skewed","Set B is left-skewed, and Set C is leptokurtic","Set A is platykurtic, and Set C is close to the normal shape"],answer:3,hint:"Read the signs: skewness for lean, kurtosis for peak and tails.",steps:[{title:"Key idea",body:"Skewness ≈ 0 symmetric, > 0 right skew. Kurtosis ≈ 0 normal tails, > 0 leptokurtic, < 0 platykurtic."},{title:"Apply to the stem",body:"A: symmetric, kurtosis −1.12 → platykurtic. B: right-skewed with long tails. C: both ≈ 0 → close to normal."},{title:"Eliminate look-alikes",body:"The other options reverse a sign or a label."}],final:"A platykurtic; C near normal → answer **D**",whyWrong:["Incorrect — negative kurtosis (Set A) is platykurtic, and Set B is strongly skewed.","Incorrect — Set C's kurtosis is about 0, and Set A's skewness is about 0.","Incorrect — Set B's skewness is positive (right skew), and Set C's kurtosis is about 0.",""],bookRef:"Book pp. 257–261"},{id:"sv-3-558",phase:3,topic:"3.1.2",qtype:"output",difficulty:2,stem:`**Surface flatness (mm)** cannot be less than zero. The output for 150 plates is:

\`\`\`
Descriptive Statistics: Flatness_mm
N     Minimum   Mean    Median   StDev   Skewness
150   0.002     0.041   0.028    0.037   1.87
\`\`\`

Which statement is BEST supported?`,options:["The data are right-skewed, which is a natural state for a characteristic bounded at zero","The data are left-skewed because the minimum is close to zero","The data are platykurtic because the mean is larger than the median","The data are bimodal because the mean and median differ"],answer:0,hint:"Read the sign of the skewness, then think about the zero floor.",steps:[{title:"Key idea",body:"Skewness > 0 = right skew; the mean (0.041) is pulled above the median (0.028)."},{title:"Apply to the stem",body:"Flatness has a natural limit at zero, and the book calls skewness a **natural state** near a limit."},{title:"Eliminate look-alikes",body:"Left skew, platykurtosis and bimodality are not shown by these values."}],final:"Right skew from a zero floor = natural → answer **A**",whyWrong:["","Incorrect — a positive skewness coefficient means the long tail is on the right.","Incorrect — mean above median is a sign of right skew, not of kurtosis.","Incorrect — a mean–median gap alone shows asymmetry, not two peaks."],bookRef:"Book pp. 257–258, 264"},{id:"sv-3-559",phase:3,topic:"3.1.2",qtype:"output",difficulty:2,stem:`A torque gauge reads to the nearest **0.5 N·m**. Output for 90 fastenings:

\`\`\`
Tally for Discrete Variables: Torque_Nm
Torque_Nm   Count
11.0          14
11.5          31
12.0          30
12.5          15
N = 90

Skewness 0.02    Anderson-Darling P-Value < 0.005
\`\`\`

Which interpretation is BEST supported?`,options:["The data are normal, because the skewness is almost zero","The data are granular, so the gauge resolution should be checked before parametric tests are trusted","The data are bimodal, because two values have the highest counts","The data are leptokurtic, because the counts are highest in the middle"],answer:1,hint:"Count the distinct values and read the p-value.",steps:[{title:"Key idea",body:"Granular data take only a few values. They can look symmetric but fail the normality test because of poor resolution."},{title:"Apply to the stem",body:"Only four values appear (0.5 N·m steps), skewness ≈ 0, yet p < 0.005 — classic granularity from measurement resolution."},{title:"Eliminate look-alikes",body:"Symmetric is not normal; there is no second peak and no tail evidence."}],final:"Four steps + p < 0.005 = granularity → answer **B**",whyWrong:["Incorrect — symmetry is not normality; the p-value is below 0.005.","","Incorrect — 31 and 30 are next to each other in the middle, not two separate peaks.","Incorrect — a peak in the middle is normal for most data; the issue is only four distinct values."],bookRef:"Book p. 263",trap:"Granular data can pass the 'looks symmetric' check and still fail normality."},{id:"sv-3-560",phase:3,topic:"3.1.2",qtype:"output",difficulty:3,stem:`Minitab's Individual Distribution Identification for **repair time (h)**, 120 jobs:

\`\`\`
Goodness of Fit Test
Distribution     AD      P
Normal           4.812   < 0.005
Exponential      2.947   < 0.003
Lognormal        0.336   0.503
Weibull          0.861   0.026
\`\`\`

Which distribution BEST fits the data?`,options:["Normal, because it has the largest AD statistic","Weibull, because its p-value is the smallest above zero","Lognormal, because it is the only fit with a p-value above 0.05","Exponential, because repair times are always exponential"],answer:2,hint:"For each fit H₀ is 'the data follow this distribution'. Which fit is not rejected?",steps:[{title:"Key idea",body:"In a goodness-of-fit test, p > 0.05 → fail to reject that the data follow the distribution; a small AD means a better fit."},{title:"Apply to the stem",body:"Only the lognormal has p > 0.05 (0.503) and the smallest AD (0.336)."},{title:"Eliminate look-alikes",body:"Normal, exponential and Weibull all have p < 0.05."}],final:"Lognormal fits (p = 0.503) → answer **C**",whyWrong:["Incorrect — a large AD and p < 0.005 mean the normal fits worst.","Incorrect — Weibull's p = 0.026 is below 0.05, so that fit is rejected.","","Incorrect — the exponential is rejected here (p < 0.003); no time measure is 'always' exponential."],bookRef:"Syllabus 3.1.2"},{id:"sv-3-561",phase:3,topic:"3.1.2",qtype:"true-false",difficulty:1,stem:"According to the book, each peak of a bimodal distribution can itself be normally distributed, even though the combined data are not. True or False?",options:["True","False"],answer:0,hint:"Think of two machines, each running normally, feeding one data set.",steps:[{title:"Key idea",body:"The book: a bimodal distribution is often **two normal distributions combined** — 2 machines, 2 operators or 2 administrators."},{title:"Apply to the stem",body:"Each peak is normal on its own; only the combined set is non-normal."}],final:"Each peak can be normal → answer **True**",whyWrong:["","Incorrect — the book describes bimodal data as often two normal distributions combined, such as two machines."],bookRef:"Book p. 262"},{id:"sv-3-562",phase:3,topic:"3.1.2",qtype:"sequence",difficulty:2,stem:`A team expected **coating thickness** to be normal before a hypothesis test. Put the book's screening steps in order:

1. Run a normality test on the data
2. If the data are non-normal, identify the class of non-normality from a graph
3. Look for and separate the underlying cause of the shape
4. Choose a parametric test or a median test for the analysis`,options:["2 → 1 → 4 → 3","1 → 4 → 2 → 3","3 → 1 → 2 → 4","1 → 2 → 3 → 4"],answer:3,hint:"Test, read the shape, find the cause, then choose the tool.",steps:[{title:"Key idea",body:"The book: check normality before every test; if non-normal, read the class, look for the underlying cause."},{title:"Apply to the stem",body:"Only then is the right test chosen — parametric if normal, median tests if not."}],final:"Test → class → cause → choose test → answer **D**",whyWrong:["Incorrect — the class cannot be identified before knowing whether the data are non-normal.","Incorrect — the test is chosen last, after the shape and its cause are understood.","Incorrect — you cannot look for the cause of a shape you have not yet tested or seen.",""],bookRef:"Book pp. 264, 370"},{id:"sv-3-563",phase:3,topic:"3.2.1",qtype:"concept",difficulty:2,stem:"Which activity is an example of **inferential** statistics?",options:["Using a random sample of 40 invoices to draw a conclusion about the mean processing time of all invoices","Plotting a histogram of the 40 invoices processed last week","Reporting the median processing time of the 40 invoices measured","Listing the shortest and longest processing times among the 40 invoices"],answer:0,hint:"Descriptive statistics summarise what you have; inferential statistics reach beyond it.",steps:[{title:"Key idea",body:"Inferential statistics draw conclusions about a **population** from a **sample**, allowing for randomness."},{title:"Apply to the stem",body:"Only the first option moves from 40 invoices to all invoices."},{title:"Eliminate look-alikes",body:"Histograms, medians and ranges of the sample are descriptive."}],final:"Sample → population conclusion = inference → answer **A**",whyWrong:["","Incorrect — a histogram summarises the data in hand; that is descriptive statistics.","Incorrect — the median of the measured invoices describes only those 40; no conclusion about all invoices is drawn.","Incorrect — the minimum and maximum describe the sample itself, not the population."],bookRef:"Book p. 267"},{id:"sv-3-564",phase:3,topic:"3.2.1",qtype:"concept",difficulty:1,stem:"How does the book define a **population**?",options:["A portion of the data taken at one time or over time","Every data point that has ever been or will ever be generated from a characteristic","One individual measurement of a characteristic","The list of units from which a sample is drawn"],answer:1,hint:"Think of 'all of it — past and future'.",steps:[{title:"Key idea",body:"Population = **every data point that has ever been or will ever be generated** from a characteristic."},{title:"Eliminate look-alikes",body:"Sample = a portion; observation = one measurement; frame = the list sampled from."}],final:"Population = all data, past and future → answer **B**",whyWrong:["Incorrect — a portion of the data is a sample.","","Incorrect — one individual measurement is an observation.","Incorrect — the list used for drawing a sample is the sampling frame."],bookRef:"Book p. 269"},{id:"sv-3-565",phase:3,topic:"3.2.1",qtype:"concept",difficulty:1,stem:"What is a **sample**, according to the book?",options:["Every data point the process has ever produced","One individual measurement of the characteristic","A portion of the population, taken at one time or over time","A number that describes the whole population"],answer:2,hint:"A subset of the whole.",steps:[{title:"Key idea",body:"Sample = **a portion (subset) of the population**, taken at one time or over time."},{title:"Eliminate look-alikes",body:"Population, observation and parameter are the other three terms in the same family."}],final:"Sample = subset of the population → answer **C**",whyWrong:["Incorrect — every data point ever produced is the population.","Incorrect — one individual measurement is an observation.","","Incorrect — a number describing the whole population is a parameter."],bookRef:"Book p. 269"},{id:"sv-3-566",phase:3,topic:"3.2.1",qtype:"concept",difficulty:2,stem:"A project aims to cut **cycle time variation** and lower the **average cycle time**. How does the book translate this mission into statistical goals?",options:["Increase the sample size and/or reduce the confidence level","Widen the specification limits and/or narrow the control limits","Remove all outliers and/or transform the data to normality","Move the process mean and/or reduce the process standard deviation"],answer:3,hint:"The book's statistical mission has two levers.",steps:[{title:"Key idea",body:"The book: the project mission translates into **moving the mean and/or reducing the standard deviation**."},{title:"Apply to the stem",body:"Lower average = move the mean; less variation = reduce σ."},{title:"Eliminate look-alikes",body:"The other pairs manipulate samples, limits or data rather than the process."}],final:"Mission = shift μ and/or reduce σ → answer **D**",whyWrong:["Incorrect — sample size and confidence affect how sure we are, not what the process does.","Incorrect — changing limits changes the targets or the chart, not the process itself.","Incorrect — deleting or transforming data changes the picture, not the process.",""],bookRef:"Book p. 267"},{id:"sv-3-567",phase:3,topic:"3.2.1",qtype:"concept",difficulty:3,stem:"Why is the **standard error of the mean** smaller than the standard deviation of the individual values?",options:["Sample means vary less from sample to sample than individual values vary from each other","The standard error ignores the largest and smallest values in the sample","The standard error uses n − 1 instead of n in its calculation","The standard error only measures the bias in the sampling method"],answer:0,hint:"What is the SE the standard deviation **of**?",steps:[{title:"Key idea",body:"The SE is the **standard deviation of the distribution of sample means**."},{title:"Apply to the stem",body:"Averaging smooths out extreme values, so means vary less than individuals — and less as n grows (s ÷ √n)."},{title:"Eliminate look-alikes",body:"Trimming, n − 1 and bias are not the reason."}],final:"SE = spread of means, which is smaller → answer **A**",whyWrong:["","Incorrect — the standard error uses all the data; it trims nothing.","Incorrect — n − 1 belongs to the sample SD formula; it is not why the SE is smaller.","Incorrect — no statistic measures bias; the SE describes random sampling error only."],bookRef:"Book p. 278"},{id:"sv-3-568",phase:3,topic:"3.2.1",qtype:"concept",difficulty:2,stem:"Which type of error is checked with an **MSA (Gage R&R)** rather than reduced by taking a larger sample?",options:["Error in sampling","Error in measurement","Bias in sampling","Lack of measurement validity"],answer:1,hint:"Which error is added by the gauge and the appraisers?",steps:[{title:"Key idea",body:"The book's four errors: sampling error, sampling bias, **measurement error** and lack of validity."},{title:"Apply to the stem",body:"Measurement error is the variation the measurement system adds — that is what MSA / Gage R&R quantifies."},{title:"Eliminate look-alikes",body:"Sampling error, bias and validity are handled by n, the sampling method and the choice of measure."}],final:"Measurement error → MSA → answer **B**",whyWrong:["Incorrect — error in sampling is the luck of the draw; it shrinks with a larger sample.","","Incorrect — bias in sampling comes from a non-random or dependent procedure, fixed by changing the method.","Incorrect — lack of validity means measuring the wrong thing; a precise gauge study cannot fix that."],bookRef:"Book p. 268"},{id:"sv-3-569",phase:3,topic:"3.2.1",qtype:"concept",difficulty:1,stem:"What does the book say about all statistics based on samples?",options:["They equal the population parameters once n is above 30","They are free of error if the sample is random","They are estimates, and all estimates could be wrong","They are valid only when the data are normal"],answer:2,hint:"Recall the book's short warning about estimates.",steps:[{title:"Key idea",body:"The book: all statistics based on samples are **estimates**, and **all estimates could be wrong**."},{title:"Eliminate look-alikes",body:"No sample size or random method removes that risk completely."}],final:"All estimates could be wrong → answer **C**",whyWrong:["Incorrect — a larger n shrinks sampling error but never makes the estimate exact.","Incorrect — a random sample still carries sampling error, the luck of the draw.","","Incorrect — sample statistics are estimates whatever the shape; normality matters for some tests."],bookRef:"Book p. 291"},{id:"sv-3-570",phase:3,topic:"3.2.1",qtype:"concept",difficulty:1,stem:"By exam convention, which denominator is used when calculating the **sample** standard deviation s?",options:["n − 1","n","n + 1","√n"],answer:0,hint:"Sample SD versus population SD.",steps:[{title:"Key idea",body:"The sample standard deviation divides the sum of squared deviations by **n − 1**."},{title:"Eliminate look-alikes",body:"Dividing by n is the population formula; √n belongs to the standard error."}],final:"Sample SD uses n − 1 → answer **A**",whyWrong:["","Incorrect — dividing by n is the population formula with σ.","Incorrect — n + 1 is not used in any standard deviation formula.","Incorrect — √n appears in the standard error (s ÷ √n), not in s itself."],bookRef:"Book p. 269"},{id:"sv-3-571",phase:3,topic:"3.2.1",qtype:"concept",difficulty:1,stem:"About what proportion of sample means fall within **±2 standard errors** of the true population mean?",options:["About 50%","About 68%","About 95%","About 99.7%"],answer:2,hint:"Apply the empirical rule to the distribution of means.",steps:[{title:"Key idea",body:"Sample means are roughly normal around μ with SD = SE, so **about 95%** lie within ±2 SE."},{title:"Apply to the stem",body:"That is why sample mean ± 2 SE gives a rough 95% interval for μ."}],final:"±2 SE ≈ 95% → answer **C**",whyWrong:["Incorrect — 50% is roughly ±0.67 standard errors.","Incorrect — about 68% fall within ±1 standard error.","","Incorrect — about 99.7% fall within ±3 standard errors."],bookRef:"Book p. 278"},{id:"sv-3-572",phase:3,topic:"3.2.1",qtype:"concept",difficulty:2,stem:"At about what sample size does the book say the standard error curve flattens and the t and Z distributions become nearly the same?",options:["About 5","About 10","About 30","About 100"],answer:2,hint:"Recall the rule of thumb for 'large' samples.",steps:[{title:"Key idea",body:"The SE falls quickly at first and then **flattens near n = 30**, where t and Z become nearly the same."},{title:"Apply to the stem",body:"Beyond about 30, extra samples buy little extra precision."}],final:"n ≈ 30 → answer **C**",whyWrong:["Incorrect — at n = 5 the SE is still falling steeply and t is much wider than Z.","Incorrect — at n = 10 the SE is still dropping noticeably.","","Incorrect — by 100 the curve is long flat; the book's turning point is earlier."],bookRef:"Book pp. 276, 279"},{id:"sv-3-573",phase:3,topic:"3.2.1",qtype:"concept",difficulty:2,stem:"After a process change, the sample average looks better. Which question does inferential statistics help the team answer?",options:["Which root cause created the original problem","Whether the measurement system is adequate","Whether the customer will accept the new process","Whether the output really changed or the result is just an unlikely sample"],answer:3,hint:"The book's key question for inference after a change.",steps:[{title:"Key idea",body:"Decisions are made from samples, so the book asks: *did the output really change, or is this just an unlikely sample?*"},{title:"Apply to the stem",body:"The CLT and hypothesis tests put a number on that risk."},{title:"Eliminate look-alikes",body:"Root cause, MSA and VOC are other questions."}],final:"Real change or unlikely sample? → answer **D**",whyWrong:["Incorrect — finding root causes uses X-sifting tools; inference judges whether a change is real.","Incorrect — measurement adequacy is an MSA question from Measure.","Incorrect — customer acceptance is a VOC question, not a statistical inference.",""],bookRef:"Book p. 267"},{id:"sv-3-574",phase:3,topic:"3.2.1",qtype:"concept",difficulty:2,stem:"Which statement about **parameters and statistics** is CORRECT?",options:["A statistic describes a sample and estimates the matching parameter","A parameter is calculated from the sample data","The symbol σ represents a sample statistic","A statistic equals its parameter whenever the sample is random"],answer:0,hint:"Parameters → populations; statistics → samples.",steps:[{title:"Key idea",body:"Parameters (μ, σ, P, N) describe the population; statistics (x̄, s, p, n) describe the sample."},{title:"Apply to the stem",body:"A statistic is an **estimate** of the matching parameter."},{title:"Eliminate look-alikes",body:"Random sampling removes bias, not sampling error."}],final:"Statistic estimates parameter → answer **A**",whyWrong:["","Incorrect — a parameter describes the population; sample values give statistics.","Incorrect — σ is the population standard deviation; s is the sample statistic.","Incorrect — random samples still differ from the parameter because of sampling error."],bookRef:"Book p. 269"},{id:"sv-3-575",phase:3,topic:"3.2.1",qtype:"concept",difficulty:3,stem:"Which statement about **lack of measurement validity** is CORRECT?",options:["It shrinks as the sample size increases","It remains however precise the gauge and however large the sample","It is the same as poor repeatability of the gauge","It is the only error that statistics can accommodate"],answer:1,hint:"Validity asks: is this the right measurement at all?",steps:[{title:"Key idea",body:"Lack of validity = the measurement does not measure what it should (a thermometer next to a furnace)."},{title:"Apply to the stem",body:"A precise gauge and a big random sample only measure the wrong thing more confidently."},{title:"Eliminate look-alikes",body:"n reduces sampling error; MSA addresses measurement error."}],final:"Validity is not fixed by precision or n → answer **B**",whyWrong:["Incorrect — only sampling error shrinks with n; validity is about what is measured.","","Incorrect — repeatability is measurement error; validity means measuring the wrong thing.","Incorrect — sampling error is the only error statistics can accommodate."],bookRef:"Book p. 268"},{id:"sv-3-576",phase:3,topic:"3.2.1",qtype:"concept",difficulty:1,stem:"Which statement about **descriptive and inferential** statistics is CORRECT?",options:["Descriptive statistics draw conclusions about the whole population","Inferential statistics need no sample data","Inferential statistics allow for randomness and uncertainty; descriptive statistics only summarise the data in hand","A histogram is an inferential tool"],answer:2,hint:"Summarise versus conclude.",steps:[{title:"Key idea",body:"Descriptive = mean, median, SD, histogram of the data you have."},{title:"Apply to the stem",body:"Inferential = models that **account for randomness and uncertainty** to reach conclusions about the process or population."}],final:"Descriptive summarises; inferential concludes → answer **C**",whyWrong:["Incorrect — conclusions about the population are inferential, not descriptive.","Incorrect — inference always starts from sample data.","","Incorrect — a histogram describes the data; it is descriptive."],bookRef:"Book p. 267"},{id:"sv-3-577",phase:3,topic:"3.2.1",qtype:"concept",difficulty:2,stem:"Which statement about decisions based on sample data is CORRECT, according to the book?",options:["A random sample removes all risk from the decision","With more than 30 data points the estimate is exact","Risk only exists when the data are attribute data","There is always a risk of being wrong because the decision uses a sample, not the population"],answer:3,hint:"Why does inference need a risk statement at all?",steps:[{title:"Key idea",body:"The book: decisions are made from **sample data, not population data**, so you are always taking a risk."},{title:"Eliminate look-alikes",body:"No sample size, method or data type makes the risk zero."}],final:"Sample decisions always carry risk → answer **D**",whyWrong:["Incorrect — random sampling removes bias, not the luck of the draw.","Incorrect — n ≈ 30 is where the SE flattens; estimates are still estimates.","Incorrect — sampling risk exists for continuous and attribute data alike.",""],bookRef:"Book p. 267"},{id:"sv-3-578",phase:3,topic:"3.2.1",qtype:"statements",difficulty:3,stem:`Which statements about the book's **die example** (1,000 rolls as the population) are CORRECT?

1. The population mean changed when larger samples were drawn.
2. Each sample drawn from the same population gave a different mean.
3. As the sample size grew, the sample means clustered more closely around the population mean.
4. Samples of n = 5 gave the narrowest range of sample means.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"The population is fixed; what changes from sample to sample?",steps:[{title:"Key idea",body:"Every sample gives a different mean — that is **sampling error**."},{title:"Apply to the stem",body:"The range of five sample means fell from 1.2 (n = 5) to 0.63 (n = 30), so 2 and 3 are true."},{title:"Eliminate look-alikes",body:"1 confuses estimates with the parameter; 4 reverses the trend."}],final:"True: 2 and 3 → answer **B**",whyWrong:["Incorrect — statement 1 is false: the population is fixed; only the sample estimates moved.","","Incorrect — statement 4 is false: n = 5 gave the widest range (1.2), n = 30 the narrowest.","Incorrect — both are false: the population mean was fixed and n = 5 gave the widest range."],bookRef:"Book pp. 270–275",trap:"The book's wording 'the mean and standard deviation decrease' means their spread from sample to sample decreases, not their values."},{id:"sv-3-579",phase:3,topic:"3.2.1",qtype:"statements",difficulty:3,stem:`Which statements about the **types of error** in an inference are CORRECT?

1. Readings from a thermometer placed beside a furnace are an example of error in sampling.
2. A larger sample cures a lack of measurement validity.
3. Random luck-of-the-draw differences between samples are error in sampling.
4. Measuring the height of horse jockeys only to estimate everyone's height is bias in sampling.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Match each example to one of the book's four error types.",steps:[{title:"Key idea",body:"Four errors: sampling error (luck of the draw), sampling bias (jockeys only), measurement error (gauge), lack of validity (thermometer by the furnace)."},{title:"Apply to the stem",body:"3 and 4 match the book's examples; 1 mislabels validity and 2 claims n fixes it."},{title:"Eliminate look-alikes",body:"Only sampling error shrinks with a larger sample."}],final:"True: 3 and 4 → answer **C**",whyWrong:["Incorrect — both are false: the furnace thermometer is lack of validity, and n does not fix validity.","Incorrect — statement 2 is false: a bigger sample only shrinks error in sampling.","","Incorrect — statement 1 is false: the furnace thermometer measures the wrong thing, which is lack of validity."],bookRef:"Book p. 268"},{id:"sv-3-580",phase:3,topic:"3.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The book defines [?] as reasoning from facts or evidence to a logical conclusion.`,options:["estimation","hypothesis","inference","sampling"],answer:2,hint:"The topic title gives it away.",steps:[{title:"Key idea",body:"The book: **inference** = reasoning from facts or evidence to a logical conclusion."},{title:"Eliminate look-alikes",body:"Estimation, hypotheses and sampling are tools used within inference."}],final:"Inference = evidence → conclusion → answer **C**",whyWrong:["Incorrect — estimation is producing a value for a parameter, one use of inference.","Incorrect — a hypothesis is a claim to be tested, not the reasoning itself.","","Incorrect — sampling is selecting part of a population to study."],bookRef:"Book p. 267"},{id:"sv-3-581",phase:3,topic:"3.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

One individual measurement of a characteristic is called an [?].`,options:["estimate","observation","parameter","statistic"],answer:1,hint:"Population → sample → ? (the smallest unit).",steps:[{title:"Key idea",body:"Book definitions: population (all), sample (a portion), **observation** (one individual measurement)."},{title:"Eliminate look-alikes",body:"Estimates, parameters and statistics are summary numbers, not single readings."}],final:"One measurement = observation → answer **B**",whyWrong:["Incorrect — an estimate is a statistic used to approximate a parameter.","","Incorrect — a parameter is a number describing the whole population.","Incorrect — a statistic is a number calculated from a sample, such as x̄."],bookRef:"Book p. 269"},{id:"sv-3-582",phase:3,topic:"3.2.1",qtype:"not-except",difficulty:2,stem:"Which pairing of a population parameter with its sample statistic is NOT correct?",options:["N with p","μ with x̄","σ with s","σ² with s²"],answer:0,hint:"Match each Greek or capital symbol with its sample counterpart.",steps:[{title:"Key idea",body:"The book's table: μ ↔ x̄, σ ↔ s, σ² ↔ s², P ↔ p, N ↔ n."},{title:"Apply to the stem",body:"N (population size) pairs with n (sample size); p pairs with P (proportion)."}],final:"N pairs with n, not p → answer **A**",whyWrong:["","Incorrect — μ (population mean) is estimated by x̄ (sample mean); this pairing is correct.","Incorrect — σ (population SD) is estimated by s (sample SD); this pairing is correct.","Incorrect — σ² (population variance) is estimated by s² (sample variance); this pairing is correct."],bookRef:"Book p. 269"},{id:"sv-3-583",phase:3,topic:"3.2.1",qtype:"not-except",difficulty:3,stem:"A rough 95% interval for mean **dispatch time** is built as the sample mean ± 2 standard errors. Which action will NOT make this interval narrower?",options:["Repeating the study with another random sample of the same size","Taking a larger random sample","Reducing the variation of the dispatch process","Improving the measurement so that readings vary less"],answer:0,hint:"The width depends on s and n only.",steps:[{title:"Key idea",body:"Width ∝ SE = s ÷ √n. It narrows when s falls or n rises."},{title:"Apply to the stem",body:"A new sample of the same size gives a different centre but, on average, the same width."}],final:"Same n, same s → same width → answer **A**",whyWrong:["","Incorrect — a larger n lowers s ÷ √n, so the interval narrows.","Incorrect — a smaller process SD lowers s and therefore the SE.","Incorrect — less measurement variation also lowers s and narrows the interval."],bookRef:"Book p. 278"},{id:"sv-3-584",phase:3,topic:"3.2.1",qtype:"scenario",difficulty:3,stem:"To estimate the average hold time experienced by **all** callers, a team analyses only calls from customers who later completed a satisfaction survey. Which type of error does this introduce?",options:["Error in sampling","Bias in sampling","Error in measurement","Lack of measurement validity"],answer:1,hint:"Is the problem the measure, the gauge, luck — or which units were picked?",steps:[{title:"Key idea",body:"Bias in sampling = lack of independence or a systematic, non-random procedure (the book's 'jockeys only' example)."},{title:"Apply to the stem",body:"Survey responders are a self-selected group, so the sample cannot represent all callers."},{title:"Eliminate look-alikes",body:"Nothing is wrong with the clock or the definition of hold time."}],final:"Self-selected subset = sampling bias → answer **B**",whyWrong:["Incorrect — error in sampling is random luck of the draw; this selection is systematic.","","Incorrect — the hold-time clock is not in question; the problem is which calls were chosen.","Incorrect — hold time is the right measure; it is taken from the wrong set of calls."],bookRef:"Book p. 268"},{id:"sv-3-585",phase:3,topic:"3.2.1",qtype:"scenario",difficulty:2,stem:"Two supervisors time the same recorded calls with stopwatches. One starts timing at the greeting, the other at the first customer word, so their readings for the same call differ. Which type of error is this?",options:["Error in sampling","Bias in sampling","Error in measurement","Lack of measurement validity"],answer:2,hint:"Same units, different readings — where does the variation come from?",steps:[{title:"Key idea",body:"Error in measurement = variation added by the measurement system (gauge, method, appraisers)."},{title:"Apply to the stem",body:"Different start points between appraisers is a reproducibility problem — checked with Gage R&R."},{title:"Eliminate look-alikes",body:"No sampling or validity issue is described."}],final:"Appraisers disagree = measurement error → answer **C**",whyWrong:["Incorrect — the same calls are timed by both, so the luck of the draw is not involved.","Incorrect — the calls were not chosen badly; the readings of the same calls disagree.","","Incorrect — both measure handle time; the problem is inconsistency between appraisers."],bookRef:"Book p. 268"},{id:"sv-3-586",phase:3,topic:"3.2.1",qtype:"scenario",difficulty:1,stem:"A random sample of 200 survey responses gives an estimate of customer satisfaction. A second random sample of 200, drawn the same way from the same list, gives a slightly different estimate. What BEST explains the difference?",options:["Bias in sampling","Error in measurement","Lack of measurement validity","Error in sampling"],answer:3,hint:"Same method, same list, different result.",steps:[{title:"Key idea",body:"Error in sampling = random 'luck of the draw' differences between samples. It is the only error statistics can accommodate."},{title:"Apply to the stem",body:"Two random samples of the same frame will almost always give slightly different estimates."},{title:"Eliminate look-alikes",body:"Bias, measurement error and validity would affect both samples alike."}],final:"Luck of the draw = sampling error → answer **D**",whyWrong:["Incorrect — both samples were random from the same list, so no systematic selection is described.","Incorrect — the survey questions and scale are unchanged between the two samples.","Incorrect — the measure is the same for both samples; validity cannot explain a difference between them.",""],bookRef:"Book p. 268"},{id:"sv-3-587",phase:3,topic:"3.2.1",qtype:"scenario",difficulty:3,stem:"Average pick time in a warehouse fell from 4.1 min to 4.0 min after a layout change, based on two samples of **8 picks** each. The supervisor wants to announce a success. Which concept should the Green Belt raise FIRST?",options:["Sampling error: with small samples the difference may be only luck of the draw","Measurement validity: pick time may be the wrong measure","Sampling bias: the 8 picks were probably chosen by the supervisor","Granularity: pick times may have too few distinct values"],answer:0,hint:"A small difference from small samples — real or noise?",steps:[{title:"Key idea",body:"Every sample mean carries sampling error; small samples carry more."},{title:"Apply to the stem",body:"A 0.1 min drop from n = 8 may lie well inside normal sample-to-sample variation, so inference is needed before claiming success."},{title:"Eliminate look-alikes",body:"No validity, bias or resolution problem is described."}],final:"Small n, small change → check sampling error → answer **A**",whyWrong:["","Incorrect — nothing suggests pick time is the wrong measure of the change.","Incorrect — the stem gives no sign of non-random selection.","Incorrect — granularity is a shape problem; the key issue is a small difference from small samples."],bookRef:"Book pp. 278–279"},{id:"sv-3-588",phase:3,topic:"3.2.1",qtype:"best-action",difficulty:3,stem:"A Green Belt wants to know whether a new script reduced call handle time. She has chosen a 2-sample t-test as the tool and is about to design the data collection. Following the book's five-step approach, what should she do NEXT?",options:["Decide how confident she is with her data summaries","Determine what kind of data the t-test requires","Collect the handle-time data from both scripts","Restate what she wants to know about the script"],answer:1,hint:"Tool chosen → what does that tool need?",steps:[{title:"Key idea",body:"Five steps: 1 what do you want to know? 2 what tool? 3 **what kind of data does that tool require?** 4 how will you collect it? 5 how confident are you?"},{title:"Apply to the stem",body:"She is at step 2 done, so step 3 is next."},{title:"Eliminate look-alikes",body:"Collection and confidence come later; step 1 is behind her."}],final:"Step 3: data the tool requires → answer **B**",whyWrong:["Incorrect — confidence in the summaries is the last of the five steps.","","Incorrect — collection comes after knowing what data the tool needs.","Incorrect — that is step 1, which she has already completed by defining the question."],bookRef:"Book p. 268"},{id:"sv-3-589",phase:3,topic:"3.2.1",qtype:"best-action",difficulty:3,stem:"A Green Belt discovers that her baseline sample of repair times came only from the **night shift**. To fix the problem, she doubles the sample size by pulling more night-shift jobs. Was this an appropriate action?",options:["Yes, because a larger sample reduces every type of error","Yes, because the night shift is part of the population","No, because the extra jobs should have been chosen by the shift supervisor","No, because a larger sample does not remove bias in sampling"],answer:3,hint:"Which error shrinks with n, and which does not?",steps:[{title:"Key idea",body:"Only **error in sampling** shrinks with a larger sample. Bias from a non-random procedure stays."},{title:"Apply to the stem",body:"More night-shift jobs make the estimate more precise for the night shift — and still biased for the whole process."},{title:"Eliminate look-alikes",body:"The fix is to sample randomly across all shifts."}],final:"Bigger biased sample is still biased → answer **D**",whyWrong:["Incorrect — a larger sample shrinks only random sampling error, not systematic bias.","Incorrect — being part of the population does not make one shift represent all shifts.","Incorrect — letting a supervisor choose adds another non-random selection.",""],bookRef:"Book p. 268"},{id:"sv-3-590",phase:3,topic:"3.2.1",qtype:"best-action",difficulty:2,stem:"A team finds that the temperature probe for a heat-treatment study is mounted beside the furnace door instead of in the product zone. What is the BEST action?",options:["Keep the probe and collect a much larger sample","Run a Gage R&R study on the probe as it is","Relocate the probe so that it measures the product-zone temperature before collecting more data","Recalibrate the probe in its current position"],answer:2,hint:"Is the problem precision, accuracy — or measuring the wrong thing?",steps:[{title:"Key idea",body:"The book's example of **lack of measurement validity** is a thermometer placed next to a furnace."},{title:"Apply to the stem",body:"The fix is to measure what you mean to measure: move the probe to the product zone."},{title:"Eliminate look-alikes",body:"Sample size, R&R and calibration do not cure invalid measurement."}],final:"Fix validity by measuring the right thing → answer **C**",whyWrong:["Incorrect — a larger sample only shrinks sampling error; the probe still measures the wrong place.","Incorrect — Gage R&R checks precision; a precise reading of the wrong place is still invalid.","","Incorrect — calibration corrects bias of the gauge, not the choice of what is measured."],bookRef:"Book p. 268"},{id:"sv-3-591",phase:3,topic:"3.2.1",qtype:"output",difficulty:2,stem:`Two random samples of **order-packing time (s)** were taken from the same process:

\`\`\`
Descriptive Statistics: Pack_s
Sample   N    Mean    StDev   SE Mean
A        10   48.2    6.1     1.93
B        40   47.6    5.9     0.93
\`\`\`

Which statement is BEST supported?`,options:["Sample A gives the better estimate because its mean is larger","The process mean shifted between the two samples","The process is less variable during sample B because its StDev is lower","Sample B gives the more precise estimate of the process mean because its SE Mean is smaller"],answer:3,hint:"Which column describes how much the sample mean wobbles?",steps:[{title:"Key idea",body:"SE Mean = standard deviation of the sample means; smaller SE = more precise estimate."},{title:"Apply to the stem",body:"B has SE Mean 0.93 versus 1.93 for A, because n = 40 versus 10."},{title:"Eliminate look-alikes",body:"The small differences in mean and StDev are sampling error."}],final:"Smaller SE Mean = more precise → answer **D**",whyWrong:["Incorrect — a larger mean is not a better estimate; precision comes from the SE.","Incorrect — a 0.6 s gap is well inside the sampling noise of samples this size.","Incorrect — 6.1 versus 5.9 is ordinary sample-to-sample variation in s, not a process change.",""],bookRef:"Book pp. 278–279"},{id:"sv-3-592",phase:3,topic:"3.2.1",qtype:"output",difficulty:2,stem:`A Minitab exercise compares a population of 1,000 die rolls with one random sample drawn from it:

\`\`\`
Descriptive Statistics
Set                  N      Mean    StDev
Population (C1)    1000   3.551   1.669
Sample (C2)          30   3.433   1.622
\`\`\`

Which statement is CORRECT?`,options:["3.433 is a statistic that estimates the parameter 3.551; the gap is sampling error","3.433 is a parameter because it was calculated by Minitab","The gap proves that the sample was biased","3.551 is a statistic because the population is only 1,000 rolls"],answer:0,hint:"Which row is the population, and which is the sample?",steps:[{title:"Key idea",body:"Parameters describe the population (μ = 3.551); statistics describe the sample (x̄ = 3.433)."},{title:"Apply to the stem",body:"A random sample gives an estimate that differs from μ by the luck of the draw — error in sampling."},{title:"Eliminate look-alikes",body:"Software, small gaps and population size do not change the labels."}],final:"Sample mean = statistic; gap = sampling error → answer **A**",whyWrong:["","Incorrect — values from a sample are statistics, whatever software computes them.","Incorrect — random samples always differ a little from the population; a small gap is not evidence of bias.","Incorrect — in this exercise the 1,000 rolls are the whole population, so their mean is the parameter."],bookRef:"Book pp. 269–272"},{id:"sv-3-593",phase:3,topic:"3.2.1",qtype:"output",difficulty:3,stem:`Baseline **truck loading time (min)** and a sample taken after a dock change:

\`\`\`
One-Sample T: Load_min (baseline)
N    Mean    StDev   SE Mean   95% CI
20   55.0    8.1     1.81      (51.2, 58.8)

After change: N = 20, Mean = 53.5
\`\`\`

The dock manager wants to report a saving. Which conclusion is BEST supported?`,options:["The change saved time because 53.5 is lower than 55.0","The new mean lies inside the range expected from sampling error, so no real improvement can be claimed yet","The change made loading worse because 53.5 is close to the lower limit","The baseline is invalid because its interval is wider than the change"],answer:1,hint:"Compare the new mean with the baseline interval, not with the baseline point estimate.",steps:[{title:"Key idea",body:"The book: look beyond the **point estimate** to the interval around it; a small change can sit inside normal sampling noise."},{title:"Apply to the stem",body:"53.5 lies inside (51.2, 58.8), so the drop could be luck of the draw."},{title:"Eliminate look-alikes",body:"A formal test would be needed before claiming a saving."}],final:"Inside the interval → do not celebrate → answer **B**",whyWrong:["Incorrect — a lower point estimate alone ignores sampling error.","","Incorrect — a lower mean cannot show that loading got worse.","Incorrect — a wide interval reflects sampling error; it does not make the baseline invalid."],bookRef:"Book p. 278"},{id:"sv-3-594",phase:3,topic:"3.2.1",qtype:"sequence",difficulty:2,stem:`Put the steps for building a rough 95% interval for a process mean in the correct order:

1. Draw a random sample from the process
2. Calculate the sample mean and standard deviation
3. Calculate the standard error of the mean
4. Form the interval as the sample mean ± 2 standard errors`,options:["2 → 1 → 3 → 4","1 → 3 → 2 → 4","1 → 2 → 3 → 4","1 → 2 → 4 → 3"],answer:2,hint:"Each step needs the result of the step before.",steps:[{title:"Key idea",body:"SE = s ÷ √n needs s; the interval x̄ ± 2 SE needs the SE."},{title:"Apply to the stem",body:"Sample → x̄ and s → SE → interval."}],final:"Sample → statistics → SE → interval → answer **C**",whyWrong:["Incorrect — the mean and SD cannot be calculated before the sample is drawn.","Incorrect — the SE needs the sample SD, so the SD comes first.","","Incorrect — the interval uses the SE, so the SE must be calculated before it."],bookRef:"Book p. 278"},{id:"sv-3-595",phase:3,topic:"3.2.1",qtype:"sequence",difficulty:1,stem:`Put these steps of a statistical inference in the correct order:

1. Define the population of interest
2. Draw a random sample from it
3. Calculate the sample statistics
4. Draw a conclusion about the population parameter, with a stated confidence`,options:["2 → 3 → 1 → 4","1 → 3 → 2 → 4","3 → 1 → 2 → 4","1 → 2 → 3 → 4"],answer:3,hint:"Population → sample → statistic → parameter.",steps:[{title:"Key idea",body:"Inference moves from a defined population, through a sample and its statistics, back to a conclusion about the parameter."},{title:"Apply to the stem",body:"Any other order uses a result before it exists."}],final:"Population → sample → statistics → conclusion → answer **D**",whyWrong:["Incorrect — the population must be defined before a sample can represent it.","Incorrect — statistics cannot be calculated before the sample exists.","Incorrect — statistics come from a sample, so sampling must come first.",""],bookRef:"Book pp. 267–269"},{id:"sv-3-596",phase:3,topic:"3.2.2",qtype:"concept",difficulty:1,stem:"What is a **simple random sample**?",options:["A sample in which every unit of the population has an equal chance of selection","A sample made of every k-th unit after a random start","A sample that measures all units in a few randomly chosen groups","A sample drawn randomly from inside every one of several groups"],answer:0,hint:"The default scheme: no groups, no interval — just chance.",steps:[{title:"Key idea",body:"Simple random sampling gives **every unit an equal chance** of being selected."},{title:"Eliminate look-alikes",body:"Interval = systematic; few whole groups = cluster; within every group = stratified."}],final:"Equal chance for every unit → answer **A**",whyWrong:["","Incorrect — every k-th unit after a random start is systematic sampling.","Incorrect — all units in a few chosen groups is cluster sampling.","Incorrect — random selection inside every group is stratified sampling."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-597",phase:3,topic:"3.2.2",qtype:"concept",difficulty:1,stem:"Which sampling scheme takes small groups of **3–5 consecutive units** at regular intervals?",options:["Cluster sampling","Rational subgrouping","Stratified sampling","Systematic sampling"],answer:1,hint:"Which scheme is built for control charts?",steps:[{title:"Key idea",body:"Rational subgroups: **3–5 consecutive units** at a regular frequency, so variation inside a subgroup is short-term only."},{title:"Eliminate look-alikes",body:"Used for control charts and short-term capability; never mix machines in one subgroup."}],final:"Consecutive small groups = rational subgroups → answer **B**",whyWrong:["Incorrect — cluster sampling takes all units of a few randomly chosen natural groups.","","Incorrect — stratified sampling takes random units from inside every stratum.","Incorrect — systematic sampling takes single units at a fixed interval, not consecutive groups."],bookRef:"Book pp. 517–519"},{id:"sv-3-598",phase:3,topic:"3.2.2",qtype:"concept",difficulty:1,stem:"In systematic sampling, what is the sampling interval k based on?",options:["The number of strata in the population","The square root of the population size","The population size divided by the required sample size","The subgroup size used on the control chart"],answer:2,hint:"Spread n picks evenly through N units.",steps:[{title:"Key idea",body:"k = N ÷ n: one unit is taken every k units after a random start."},{title:"Eliminate look-alikes",body:"Strata, square roots and subgroup sizes belong to other schemes."}],final:"k = N ÷ n → answer **C**",whyWrong:["Incorrect — strata belong to stratified sampling; systematic sampling has no strata.","Incorrect — no square-root rule sets the interval; it comes from N and n.","","Incorrect — subgroup size belongs to rational subgrouping for SPC."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-599",phase:3,topic:"3.2.2",qtype:"concept",difficulty:3,stem:"Which is a known weakness of **cluster** sampling?",options:["A complete list of every unit in the population is always needed","It is biased whenever the process has a regular cycle","It needs information on which stratum every unit belongs to","Units inside a cluster tend to be alike, so the estimate is less precise"],answer:3,hint:"What happens when you measure whole groups of similar units?",steps:[{title:"Key idea",body:"Cluster sampling measures **all** units in a few clusters. Units in one cluster are often alike."},{title:"Apply to the stem",body:"Alike units add little new information, so precision is lower than a random sample of the same size."},{title:"Eliminate look-alikes",body:"Cycles hit systematic sampling; stratum data is needed for stratified sampling."}],final:"Clusters alike inside → less precise → answer **D**",whyWrong:["Incorrect — cluster sampling only needs a list of clusters, which is one of its advantages.","Incorrect — bias from a regular cycle is the weakness of systematic sampling.","Incorrect — stratum information is the requirement of stratified sampling.",""],bookRef:"Syllabus 3.2.2"},{id:"sv-3-600",phase:3,topic:"3.2.2",qtype:"concept",difficulty:2,stem:"Why does the book say a list of **registered voters** may be a poor frame for a study of 'the adult public'?",options:["It misses adults who are not registered, so they cannot be sampled","It contains too many names to sample from","Its names are already in random order","It lists every adult more than once"],answer:0,hint:"A frame must cover the whole population.",steps:[{title:"Key idea",body:"A good frame is **complete** and lists every element once."},{title:"Apply to the stem",body:"Unregistered adults are part of the population but not on the list, so no draw can reach them."},{title:"Eliminate look-alikes",body:"Size and order do not make a frame complete."}],final:"Incomplete frame misses part of the population → answer **A**",whyWrong:["","Incorrect — a large frame is fine; the problem is who is missing from it.","Incorrect — the order of names is irrelevant to whether the frame is complete.","Incorrect — the book's concern is people left out, not duplicates."],bookRef:"Book p. 141"},{id:"sv-3-601",phase:3,topic:"3.2.2",qtype:"concept",difficulty:2,stem:"Which scheme is usually the MOST efficient when the population is spread across many distant sites and travel to each site is costly?",options:["Cluster sampling","Simple random sampling","Stratified sampling","Systematic sampling"],answer:0,hint:"Which scheme lets you visit only a few places?",steps:[{title:"Key idea",body:"Cluster sampling picks **a few natural groups at random** and measures every unit inside them."},{title:"Apply to the stem",body:"Only the chosen sites are visited, which cuts travel when access is costly."},{title:"Eliminate look-alikes",body:"The trade-off is lower precision, because units in a cluster tend to be alike."}],final:"Costly access → cluster → answer **A**",whyWrong:["","Incorrect — a simple random sample would scatter units across many sites, raising travel cost.","Incorrect — stratified sampling needs units from every stratum, so every site type must be visited.","Incorrect — every k-th unit across the population would still require visiting most sites."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-602",phase:3,topic:"3.2.2",qtype:"concept",difficulty:1,stem:"Which is the BEST description of a **representative** sample?",options:["One that contains only the cleanest, most complete records","One whose make-up mirrors the population because units were chosen without bias","One that is at least half the size of the population","One that was chosen by the process owner as typical"],answer:1,hint:"Representative = a fair miniature of the whole.",steps:[{title:"Key idea",body:"If sampling is done well, what you see in the sample **represents the population**."},{title:"Apply to the stem",body:"That needs a complete frame and a random, unbiased selection."},{title:"Eliminate look-alikes",body:"Clean records, sheer size and hand-picking do not guarantee it."}],final:"Unbiased choice → representative → answer **B**",whyWrong:["Incorrect — choosing only clean records favours one kind of unit and biases the sample.","","Incorrect — size reduces sampling error, but a large sample can still be unrepresentative.","Incorrect — hand-picked 'typical' units are a judgement selection, open to bias."],bookRef:"Book p. 141"},{id:"sv-3-603",phase:3,topic:"3.2.2",qtype:"concept",difficulty:1,stem:"Which sampling scheme do the standard confidence-interval and sample-size formulas assume by default?",options:["Cluster sampling","Convenience sampling","Simple random sampling","Systematic sampling"],answer:2,hint:"The formulas need every unit to have an equal, independent chance.",steps:[{title:"Key idea",body:"The usual formulas for SE, intervals and sample size assume a **simple random sample**."},{title:"Eliminate look-alikes",body:"Other schemes need care or adjustment; convenience samples cannot be fixed by formulas."}],final:"Formulas assume simple random sampling → answer **C**",whyWrong:["Incorrect — cluster samples need adjusted formulas because units within a cluster are alike.","Incorrect — convenience samples are not chosen by chance, so no formula can describe their error.","","Incorrect — systematic sampling only behaves like random sampling when no cycle is present."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-604",phase:3,topic:"3.2.2",qtype:"concept",difficulty:2,stem:"Why should a baseline sample be spread across **shifts and days**?",options:["So that the sample size can be smaller than the formula requires","So that the data become normally distributed","So that the measurement system error is removed","So that the sample reflects all the normal sources of variation in the process"],answer:3,hint:"A sample from one condition represents only that condition.",steps:[{title:"Key idea",body:"Sampling only one shift, day or time is a classic source of **bias**."},{title:"Apply to the stem",body:"Spreading the sample lets every normal condition appear, so the baseline represents the whole process."},{title:"Eliminate look-alikes",body:"It does not change n, normality or gauge error."}],final:"Spread the sample to avoid bias → answer **D**",whyWrong:["Incorrect — spreading the sample does not reduce the size the decision needs.","Incorrect — spreading the sample does not change the shape of the process data.","Incorrect — measurement error is addressed by MSA, not by when the sample is taken.",""],bookRef:"Book p. 268"},{id:"sv-3-605",phase:3,topic:"3.2.2",qtype:"concept",difficulty:1,stem:"Which Minitab command does the book use to draw a **random sample** from a column of data?",options:["Calc > Random Data > Sample from Columns","Stat > Basic Statistics > Display Descriptive Statistics","Stat > Quality Tools > Capability Analysis","Graph > Histogram > With Fit"],answer:0,hint:"Random selection is a Calc menu task.",steps:[{title:"Key idea",body:"The book draws random samples with **Calc > Random Data > Sample from Columns**."},{title:"Eliminate look-alikes",body:"The other menus summarise, assess capability or graph data."}],final:"Calc > Random Data > Sample from Columns → answer **A**",whyWrong:["","Incorrect — Display Descriptive Statistics summarises data; it does not select a sample.","Incorrect — Capability Analysis compares the process with the specification.","Incorrect — a histogram shows the shape of data already collected."],bookRef:"Book p. 271"},{id:"sv-3-606",phase:3,topic:"3.2.2",qtype:"concept",difficulty:2,stem:"According to the book, what does the required sample size for a comparison MAINLY depend on?",options:["The number of people on the project team","The size of the difference to detect (delta) and the standard deviation","The length of the project timeline","The number of specification limits"],answer:1,hint:"Small differences and noisy data need more data.",steps:[{title:"Key idea",body:"The book: 'How many samples? It depends on the size of the difference (delta) and the standard deviation.'"},{title:"Apply to the stem",body:"Small delta and large σ need large samples; α and power also play a part."},{title:"Eliminate look-alikes",body:"Team, timeline and specs are not drivers of n."}],final:"n depends on delta and σ → answer **B**",whyWrong:["Incorrect — team size has no effect on how many data points a decision needs.","","Incorrect — the timeline affects how fast data can be collected, not how many are needed.","Incorrect — the number of specs does not set n."],bookRef:"Book p. 285"},{id:"sv-3-607",phase:3,topic:"3.2.2",qtype:"concept",difficulty:2,stem:"A Champion asks the team to 'take more samples just to be sure', although the correct sample size was calculated and collected. What does the book say?",options:["Yes — more samples always improve a decision","Yes — the sample size should always be doubled for safety","No — extra samples are not needed if the correct number was taken the first time","No — the sample should be cut back to save cost"],answer:2,hint:"The right n is designed, not guessed.",steps:[{title:"Key idea",body:"The book: 'Should we take more samples just to be sure? **No — not if you took the correct number the first time.**'"},{title:"Eliminate look-alikes",body:"A properly calculated n already balances risk and cost."}],final:"Correct n the first time is enough → answer **C**",whyWrong:["Incorrect — beyond the right n, extra data add cost with little gain.","Incorrect — doubling for safety has no basis when n was set by delta, σ, α and power.","","Incorrect — cutting below the calculated n raises the risk of a wrong decision."],bookRef:"Book p. 285"},{id:"sv-3-608",phase:3,topic:"3.2.2",qtype:"concept",difficulty:3,stem:"Which statement about **strata** and **clusters** is CORRECT?",options:["Strata should be alike, while clusters should differ from each other","In stratified sampling only a few strata are visited","In cluster sampling units are drawn from every cluster","Strata should differ from each other, while each cluster should resemble the population"],answer:3,hint:"Exam pair: who is sampled inside each group?",steps:[{title:"Key idea",body:"Stratified: groups **differ**, so sample randomly inside every one."},{title:"Apply to the stem",body:"Cluster: groups are alike (each a mini-population), so take all units of a few."},{title:"Eliminate look-alikes",body:"The distractors swap the 'every' and 'few' rules."}],final:"Strata differ; clusters alike → answer **D**",whyWrong:["Incorrect — this reverses the rule: strata differ, clusters are miniatures of the population.","Incorrect — stratified sampling samples inside **every** stratum.","Incorrect — cluster sampling takes all units of a **few** clusters.",""],bookRef:"Syllabus 3.2.2"},{id:"sv-3-609",phase:3,topic:"3.2.2",qtype:"concept",difficulty:2,stem:"Which statement about **error in sampling** is CORRECT?",options:["It is the random luck-of-the-draw difference between samples, and it shrinks as n grows","It is a systematic error caused by sampling only one shift","It is removed completely by a random selection method","It is checked with a Gage R&R study"],answer:0,hint:"Random versus systematic error.",steps:[{title:"Key idea",body:"Error in sampling = random sample-to-sample differences. It **shrinks with larger n**."},{title:"Apply to the stem",body:"In the die example the range of five means fell from 1.2 (n = 5) to 0.63 (n = 30)."},{title:"Eliminate look-alikes",body:"Bias is systematic; measurement error belongs to MSA."}],final:"Sampling error is random and shrinks with n → answer **A**",whyWrong:["","Incorrect — sampling only one shift is bias in sampling, which does not shrink with n.","Incorrect — random selection removes bias; luck-of-the-draw error remains.","Incorrect — Gage R&R checks measurement error, not sampling error."],bookRef:"Book p. 268"},{id:"sv-3-610",phase:3,topic:"3.2.2",qtype:"concept",difficulty:3,stem:"Which statement about **stratified** sampling is CORRECT?",options:["It selects all units in a few randomly chosen strata","It ensures that small but important groups appear in the sample","It is less precise than simple random sampling when the strata differ","It can be used without knowing which stratum each unit belongs to"],answer:1,hint:"What does sampling inside every group guarantee?",steps:[{title:"Key idea",body:"Stratified sampling draws randomly **inside every stratum**."},{title:"Apply to the stem",body:"So every stratum, however small, is represented — a simple random sample might miss it by chance."},{title:"Eliminate look-alikes",body:"Its cost is the need for stratum information."}],final:"Every stratum is represented → answer **B**",whyWrong:["Incorrect — taking all units in a few groups is cluster sampling.","","Incorrect — when strata differ, stratifying is usually more precise than simple random sampling.","Incorrect — stratum membership must be known to sample within each stratum."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-611",phase:3,topic:"3.2.2",qtype:"statements",difficulty:2,stem:`Which statements about sampling schemes are CORRECT?

1. Systematic sampling suits a steady stream of transactions.
2. Systematic sampling should begin at a randomly chosen start point.
3. Stratified sampling takes all units in a few randomly chosen strata.
4. Cluster sampling works best when the clusters differ strongly from each other.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Check each statement against the scheme it names.",steps:[{title:"Key idea",body:"Systematic: every k-th unit after a **random start**; suits a steady stream. So 1 and 2 are true."},{title:"Apply to the stem",body:"3 describes cluster sampling; 4 is wrong because clusters should be alike, each a mini-population."},{title:"Eliminate look-alikes",body:"Strata differ; clusters are alike."}],final:"True: 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: all units in a few groups describes cluster sampling.","Incorrect — both are false: 3 describes clusters and 4 reverses the cluster rule.","Incorrect — statement 4 is false: clusters should each resemble the population."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-612",phase:3,topic:"3.2.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

In [?] sampling, a few natural groups are chosen at random and every unit inside them is measured.`,options:["cluster","simple random","stratified","systematic"],answer:0,hint:"Few whole groups, all units inside.",steps:[{title:"Key idea",body:"**Cluster** sampling: choose a few clusters at random, measure all their units."},{title:"Eliminate look-alikes",body:"Stratified samples within every group; systematic uses an interval."}],final:"Few whole groups = cluster → answer **A**",whyWrong:["","Incorrect — simple random sampling picks individual units with equal chance, not whole groups.","Incorrect — stratified sampling takes random units from inside every group.","Incorrect — systematic sampling takes every k-th unit."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-613",phase:3,topic:"3.2.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

An identifiable list of the population from which the sample is drawn is called the sampling [?].`,options:["frame","plan","stratum","unit"],answer:0,hint:"The list you draw from.",steps:[{title:"Key idea",body:"Book p. 141: the **frame** is an identifiable list of the population from which the sample is drawn."},{title:"Eliminate look-alikes",body:"A good frame is complete and lists every element once."}],final:"List to sample from = frame → answer **A**",whyWrong:["","Incorrect — a sampling plan describes how, when and how many to sample, not the list itself.","Incorrect — a stratum is one subgroup of the population in stratified sampling.","Incorrect — a unit is a single item that may be selected."],bookRef:"Book p. 141"},{id:"sv-3-614",phase:3,topic:"3.2.2",qtype:"not-except",difficulty:2,stem:"Which is NOT a feature of a good **sampling frame**?",options:["It covers the whole population of interest","It lists every element only once","It contains mainly the units that are easiest to reach","It is up to date for the period being studied"],answer:2,hint:"Three describe completeness; one describes convenience.",steps:[{title:"Key idea",body:"A good frame is **complete** and lists **every element once**."},{title:"Apply to the stem",body:"A list of the easiest units to reach is a convenience list, which builds bias into any sample drawn from it."}],final:"Convenience list ≠ good frame → answer **C**",whyWrong:["Incorrect — covering the whole population is the first requirement of a good frame.","Incorrect — listing each element once is part of the book's definition of a good frame.","","Incorrect — an out-of-date list misses or wrongly includes units."],bookRef:"Book p. 141"},{id:"sv-3-615",phase:3,topic:"3.2.2",qtype:"not-except",difficulty:2,stem:"Which is NOT a benefit of sampling instead of measuring the whole population?",options:["It costs much less money","It takes much less time and effort","It provides a basis for statistical inference","It removes all uncertainty from the conclusion"],answer:3,hint:"What does a sample always keep?",steps:[{title:"Key idea",body:"Purpose of sampling: a sufficiently accurate inference for **much less time, money and effort**, and a basis for inference."},{title:"Apply to the stem",body:"A sample always carries sampling error, so uncertainty is reduced, never removed."}],final:"Sampling never removes uncertainty → answer **D**",whyWrong:["Incorrect — lower cost is a stated purpose of sampling.","Incorrect — less time and effort is a stated purpose of sampling.","Incorrect — sampling gives the basis for inference about the population.",""],bookRef:"Book p. 141"},{id:"sv-3-616",phase:3,topic:"3.2.2",qtype:"not-except",difficulty:1,stem:"Which sampling method does NOT select units by chance?",options:["Convenience sampling","Simple random sampling","Stratified random sampling","Systematic sampling with a random start"],answer:0,hint:"Which method picks what is easy rather than what is random?",steps:[{title:"Key idea",body:"Probability methods: simple random, stratified random, systematic with a random start, cluster."},{title:"Apply to the stem",body:"**Convenience sampling** takes whatever is easy to reach, which invites bias."}],final:"Convenience = not by chance → answer **A**",whyWrong:["","Incorrect — simple random sampling gives every unit an equal chance.","Incorrect — stratified random sampling selects by chance inside each stratum.","Incorrect — the random start makes the selection of a systematic sample a chance event."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-617",phase:3,topic:"3.2.2",qtype:"scenario",difficulty:2,stem:"Three plants make the same bracket on equipment of very different ages, and quality is expected to differ between plants. The team must estimate the overall defect rate and make sure every plant is represented. Which sampling technique is MOST appropriate?",options:["Stratified sampling, with a random sample from each plant","Cluster sampling, choosing one plant and checking all its brackets","Systematic sampling of every 50th bracket from one plant","Simple random sampling from the plant nearest the team"],answer:0,hint:"Groups that differ, all of which must appear.",steps:[{title:"Key idea",body:"Stratified sampling: split into groups that **differ** and sample randomly inside **every** group."},{title:"Apply to the stem",body:"The plants are the strata; each must contribute to the estimate."},{title:"Eliminate look-alikes",body:"Every other option samples a single plant."}],final:"Different plants → stratify → answer **A**",whyWrong:["","Incorrect — one plant cannot represent three plants that are expected to differ.","Incorrect — sampling only one plant leaves the other two unrepresented.","Incorrect — sampling only the nearest plant is a convenience choice and biased."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-618",phase:3,topic:"3.2.2",qtype:"scenario",difficulty:1,stem:"An auditor takes a random number between 1 and 25 as a start, then selects **every 25th invoice** from the day's sequential invoice run. Which sampling technique is this?",options:["Cluster sampling","Systematic sampling","Rational subgrouping","Stratified sampling"],answer:1,hint:"Fixed interval after a random start.",steps:[{title:"Key idea",body:"Systematic sampling = every k-th unit after a random start (here k = 25)."},{title:"Eliminate look-alikes",body:"No clusters, subgroups or strata are involved."}],final:"Every k-th after random start = systematic → answer **B**",whyWrong:["Incorrect — cluster sampling would take all invoices in a few chosen batches.","","Incorrect — rational subgroups are small groups of consecutive units for control charts.","Incorrect — no groups that differ are defined, and nothing is sampled within groups."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-619",phase:3,topic:"3.2.2",qtype:"scenario",difficulty:2,stem:"To check moisture in bagged cement, an inspector samples bags only from the **top layer** of each pallet because they are easiest to reach. Which problem does this create?",options:["Sampling error, because the luck of the draw is too large","Measurement error, because the moisture meter is imprecise","Sampling bias, because only one easily reached position is sampled","Low precision, because the bags in a cluster are alike"],answer:2,hint:"Easiest to reach ≠ chosen by chance.",steps:[{title:"Key idea",body:"A convenience sample favours one condition — here the top layer, which may dry or absorb moisture differently."},{title:"Apply to the stem",body:"That is **sampling bias**; the fix is random selection of positions on each pallet."},{title:"Eliminate look-alikes",body:"Sampling error, gauge error and cluster precision are not the issue."}],final:"Top layer only = convenience bias → answer **C**",whyWrong:["Incorrect — the problem is systematic, not random; a larger sample from the top layer stays biased.","Incorrect — nothing in the stem questions the meter.","","Incorrect — this is not a cluster design; it is a convenience choice of position."],bookRef:"Book p. 268"},{id:"sv-3-620",phase:3,topic:"3.2.2",qtype:"scenario",difficulty:1,stem:"An auditor numbers every invoice in the complete invoice register and uses a random number generator to choose **60** of them. Which sampling technique is this?",options:["Cluster sampling","Stratified sampling","Systematic sampling","Simple random sampling"],answer:3,hint:"Complete list + random numbers.",steps:[{title:"Key idea",body:"Simple random sampling: every unit in a complete frame has an equal chance, chosen by random numbers."},{title:"Eliminate look-alikes",body:"No clusters, strata or interval are involved."}],final:"Random numbers from full list = simple random → answer **D**",whyWrong:["Incorrect — no groups are chosen; individual invoices are drawn.","Incorrect — the register is not split into strata first.","Incorrect — there is no fixed interval between selected invoices.",""],bookRef:"Syllabus 3.2.2"},{id:"sv-3-621",phase:3,topic:"3.2.2",qtype:"best-action",difficulty:2,stem:"A team needs a sample of invoices to baseline processing time. The billing supervisor offers to pick the invoices himself 'to save time'. What is the BEST response?",options:["Draw the invoices with a random method from the complete invoice list","Accept, provided the supervisor picks at least 30 invoices","Accept, provided the supervisor picks only typical invoices","Ask the supervisor to pick the invoices with the fewest problems"],answer:0,hint:"Who chooses — a person or chance?",steps:[{title:"Key idea",body:"Bias sources include letting the process owner pick 'good' examples."},{title:"Apply to the stem",body:"Draw from a complete frame using a random method (for example Minitab's Sample from Columns)."},{title:"Eliminate look-alikes",body:"Size and 'typical' labels do not cure a non-random choice."}],final:"Random draw, not hand-picked → answer **A**",whyWrong:["","Incorrect — a larger hand-picked sample is still a judgement sample open to bias.","Incorrect — 'typical' cases chosen by the owner are a classic source of bias.","Incorrect — choosing the cleanest invoices biases the baseline toward good results."],bookRef:"Book p. 268"},{id:"sv-3-622",phase:3,topic:"3.2.2",qtype:"best-action",difficulty:3,stem:"During a baseline study, operators were told in advance which hours would be sampled, and they worked extra carefully in those hours. The Green Belt changes the plan so that samples are taken at random, unannounced times. Was this an appropriate action?",options:["Yes, because the sample should reflect the process running normally","Yes, because unannounced sampling reduces the sample size needed","No, because operators must always be told when they are sampled","No, because careful work during sampling improves the data quality"],answer:0,hint:"What should a baseline describe?",steps:[{title:"Key idea",body:"To prevent bias, **let the process run normally** while you sample."},{title:"Apply to the stem",body:"Announced hours changed behaviour, so those samples did not represent normal work; random, unannounced times fix that."},{title:"Eliminate look-alikes",body:"Sample size is not the reason, and unusual care is not 'quality'."}],final:"Sample the process as it normally runs → answer **A**",whyWrong:["","Incorrect — timing does not change the required n; it changes whether the data are representative.","Incorrect — the goal is a sample of normal operation; announced hours distorted it.","Incorrect — 'better' data from unusual effort misstate the real process, biasing the baseline."],bookRef:"Book p. 268"},{id:"sv-3-623",phase:3,topic:"3.2.2",qtype:"best-action",difficulty:3,stem:"A team studying **why customers leave** uses a frame of active accounts, which omits accounts closed during the month. The Green Belt keeps the same frame and increases the sample size. Was this an appropriate action?",options:["Yes, because a larger sample reduces sampling error","Yes, because active accounts are part of the population","No, because a larger sample cannot represent units missing from the frame","No, because a frame should only be used for stratified samples"],answer:2,hint:"Can a draw reach units that are not on the list?",steps:[{title:"Key idea",body:"If the frame misses part of the population, **no sample drawn from it can represent that part**, however large."},{title:"Apply to the stem",body:"Closed accounts are exactly the customers who left, so the frame must be fixed first."},{title:"Eliminate look-alikes",body:"n reduces random error only."}],final:"Fix the frame, not the sample size → answer **C**",whyWrong:["Incorrect — less sampling error does not help when the key units are not on the list.","Incorrect — the customers who left, the focus of the study, are not on the frame at all.","","Incorrect — every probability sampling scheme draws from a frame."],bookRef:"Book p. 141"},{id:"sv-3-624",phase:3,topic:"3.2.2",qtype:"output",difficulty:2,stem:`A sample of 200 parts was drawn for a scrap study. Minitab tallies the sample by line; the team adds each line's share of production:

\`\`\`
Tally for Discrete Variables: Line
Line    Count   Percent   Share of production
L1        104     52.00   35%
L2         86     43.00   25%
L3         10      5.00   40%
N = 200
\`\`\`

Which conclusion is BEST supported?`,options:["The sample is representative because N is 200","Line 3 is badly under-represented, so the sample may not represent total production","Line 1 is under-represented compared with its share of production","The sample is a proportional stratified sample"],answer:1,hint:"Compare the Percent column with the share of production.",steps:[{title:"Key idea",body:"A representative sample should mirror the population's make-up."},{title:"Apply to the stem",body:"L3 makes 40% of production but only 5% of the sample — a clear imbalance that suggests biased selection."},{title:"Eliminate look-alikes",body:"Size does not cure bias; L1 is over-, not under-represented."}],final:"Sample mix ≠ production mix → not representative → answer **B**",whyWrong:["Incorrect — a large N does not fix an unbalanced selection.","","Incorrect — line 1 has 52% of the sample against 35% of production: it is over-represented.","Incorrect — in a proportional stratified sample each line's percent would match its share."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-625",phase:3,topic:"3.2.2",qtype:"output",difficulty:2,stem:`Minitab Power and Sample Size output for a 2-sample t-test (α = 0.05, power = 0.80, σ = 4):

\`\`\`
Difference   Sample Size   Target Power   Actual Power
1            253           0.8            0.800655
2             64           0.8            0.801460
4             17           0.8            0.807037
\`\`\`

Which statement is BEST supported?`,options:["Detecting a larger difference requires a larger sample per group","The sample size does not depend on the difference to detect","Detecting a smaller difference requires a much larger sample per group","A difference of 1 can be detected with 17 per group"],answer:2,hint:"Read the Sample Size column down the Difference column.",steps:[{title:"Key idea",body:"The book: n depends on **delta and σ** — small differences need large samples."},{title:"Apply to the stem",body:"Difference 1 → 253 per group; difference 4 → 17 per group."},{title:"Eliminate look-alikes",body:"The other statements reverse or misread the table."}],final:"Smaller delta → larger n → answer **C**",whyWrong:["Incorrect — this reverses the output: a difference of 4 needs only 17.","Incorrect — sample size changes from 253 to 17 as the difference changes.","","Incorrect — 17 per group is the size for a difference of 4, not 1."],bookRef:"Book p. 285"},{id:"sv-3-626",phase:3,topic:"3.2.2",qtype:"output",difficulty:3,stem:`A stratified customer survey drew the following sample:

\`\`\`
Segment      Customers in segment   Sampled
Consumer     60,000                 150
SME          30,000                 150
Enterprise   10,000                 150
\`\`\`

Which statement about this design is CORRECT?`,options:["It uses proportional allocation, because each segment has the same sample size","It is a cluster sample, because all three segments are included","It is a simple random sample of all customers","It uses equal allocation, so the small Enterprise segment is sampled more heavily relative to its size"],answer:3,hint:"Same number from each segment, though the segments differ in size.",steps:[{title:"Key idea",body:"Stratified sampling samples randomly inside **every** stratum; allocation can be equal or proportional."},{title:"Apply to the stem",body:"150 from each segment despite very different sizes = equal allocation; Enterprise is over-sampled relative to its size, so overall results need weighting."},{title:"Eliminate look-alikes",body:"It is neither proportional, cluster nor simple random."}],final:"Equal allocation stratified sample → answer **D**",whyWrong:["Incorrect — proportional allocation would give the largest segment the largest sample.","Incorrect — cluster sampling takes all units of a few groups; here units are sampled within every group.","Incorrect — sampling a fixed number inside each segment is stratified, not simple random.",""],bookRef:"Syllabus 3.2.2"},{id:"sv-3-627",phase:3,topic:"3.2.2",qtype:"output",difficulty:3,stem:`A bottling line has **6 filling heads** used in fixed rotation. An inspector samples every 6th bottle. The sample log shows:

\`\`\`
Sample   Bottle no.   Filling head
1         4           4
2        10           4
3        16           4
4        22           4
5        28           4
...      ...          4
\`\`\`

What is the MAIN problem with this sample?`,options:["The interval matches the head rotation, so only head 4 is ever sampled","The sample is too small to estimate the fill volume","The bottles were chosen by convenience rather than by an interval","The data are granular because only one head appears"],answer:0,hint:"Compare the sampling interval with the process cycle.",steps:[{title:"Key idea",body:"Systematic sampling is biased when the process has a cycle that matches the interval k."},{title:"Apply to the stem",body:"k = 6 equals the 6-head rotation, so every sampled bottle comes from head 4; the other five heads are never seen."},{title:"Eliminate look-alikes",body:"Size, convenience and granularity are not the issue."}],final:"Interval = cycle → systematic bias → answer **A**",whyWrong:["","Incorrect — the problem is which bottles are chosen, not how many.","Incorrect — the bottles were chosen by a fixed interval; the interval itself is the problem.","Incorrect — granularity is about measurement resolution, not about which head is sampled."],bookRef:"Syllabus 3.2.2"},{id:"sv-3-628",phase:3,topic:"3.2.2",qtype:"true-false",difficulty:2,stem:"In stratified sampling, the strata should be alike in the characteristic being measured. True or False?",options:["True","False"],answer:1,hint:"Strata differ; clusters are alike.",steps:[{title:"Key idea",body:"Stratify when groups **differ** (regions, vendors, shifts), then sample within each."},{title:"Apply to the stem",body:"If the strata were alike, stratifying would add little; the statement is false."}],final:"Strata should differ → answer **False**",whyWrong:["Incorrect — strata are chosen because they differ; alike groups are the idea behind clusters.",""],bookRef:"Syllabus 3.2.2"},{id:"sv-3-629",phase:3,topic:"3.2.2",qtype:"sequence",difficulty:1,stem:`Put the steps for drawing a **simple random sample** in the correct order:

1. Define the population of interest
2. Obtain a complete frame that lists every unit once
3. Select units with random numbers (for example in Minitab)
4. Collect the data from the selected units`,options:["2 → 1 → 3 → 4","1 → 2 → 3 → 4","1 → 3 → 2 → 4","1 → 2 → 4 → 3"],answer:1,hint:"Each step needs the one before it.",steps:[{title:"Key idea",body:"Population → frame → random selection → data collection."},{title:"Apply to the stem",body:"The frame must cover the defined population, and selection must come before measurement."}],final:"Population → frame → select → collect → answer **B**",whyWrong:["Incorrect — a frame cannot be judged complete before the population is defined.","","Incorrect — random numbers need a numbered frame to select from.","Incorrect — data are collected only from units already selected."],bookRef:"Book pp. 141, 271"},{id:"sv-3-630",phase:3,topic:"3.2.2",qtype:"sequence",difficulty:2,stem:`Put the steps for drawing a **systematic sample** in the correct order:

1. Confirm the population size N and the required sample size n
2. Set the interval k = N ÷ n
3. Choose a random start between 1 and k
4. Select every k-th unit from the start`,options:["2 → 1 → 3 → 4","1 → 3 → 2 → 4","1 → 2 → 3 → 4","3 → 4 → 1 → 2"],answer:2,hint:"Interval first, then start, then select.",steps:[{title:"Key idea",body:"k = N ÷ n, then a random start within the first k units, then every k-th unit."},{title:"Apply to the stem",body:"The random start keeps the selection a chance event."}],final:"N, n → k → random start → every k-th → answer **C**",whyWrong:["Incorrect — k cannot be set before N and n are known.","Incorrect — the random start lies between 1 and k, so k must be set first.","","Incorrect — selection cannot start before the interval is known."],bookRef:"Syllabus 3.2.2"}];export{e as items};
